{
  "timeZone": "Africa/Cairo",
  "dependencies": {},
  "exceptionLogging": "STACKDRIVER",
  "runtimeVersion": "V8",
  "webapp": {
    "executeAs": "USER_DEPLOYING",
    "access": "DOMAIN"
  }
}

/**
 * CORE — Bootstrap & sheet infrastructure
 * doGet routing, HTML templating (include), spreadsheet setup,
 * sheet helpers, and small cross-cutting formatting utilities.
 * Split out of Code.gs during the Sprint 5 restructure.
 */

/**
 * BIOETHICS PORTAL — Faculty of Biotechnology, MSA University
 * SPRINT 4
 * ---------------------------------------------------------
 * Server-side: serves the SPA shell, manages Google Sheets as
 * the application database, and exposes draft/load/submit APIs
 * used by the Ethics Application Wizard.
 *
 * Sprint 1 + Sprint 2 + Sprint 3 behaviour is unchanged. Sprint 4 adds
 * the Reviewer Portal on top of the same spreadsheet:
 *   - Reviewer identity (gated by a pre-provisioned Reviewers sheet,
 *     NOT open self-signup like students)
 *   - Reviewer dashboard (assigned / in-progress / completed counts)
 *   - Assigned application list, sourced from a new Assignments sheet
 *   - Section-by-section read-only view of the student's submitted
 *     application + required annex checklist state
 *   - Digital comments per section
 *   - Interactive rubric with automatic weighted score calculation
 *   - Digital signature + decision (Approve / Minor Revisions /
 *     Major Revisions / Reject) that finalizes a review
 *   - Review history for the signed-in reviewer
 *
 * Coordinator / chair flows (assigning reviewers, workload balancing,
 * multi-reviewer consensus) remain Sprint 5 scope. For now,
 * `adminAssignReviewer()` / `adminRegisterReviewer()` are simple
 * server-side utilities (run from the Apps Script editor, or wired to
 * a temporary admin affordance) that stand in for the Sprint 5
 * Coordinator UI — see PROJECT.md §7.
 */

var PROP_SPREADSHEET_ID = 'SPREADSHEET_ID';
var DEFAULT_SEMESTER = 'Fall 2026';

var SHEET_CONFIG = 'Config';
var SHEET_STUDENTS = 'Students';
var SHEET_APPLICATIONS = 'Applications';
// Sprint 4:
var SHEET_REVIEWERS = 'Reviewers';
var SHEET_ASSIGNMENTS = 'Assignments';
var SHEET_REVIEWS = 'Reviews';

// Sprint 3: 'annexProgress' appended at the end so existing Sprint 2
// spreadsheets migrate cleanly (see ensureAnnexProgressColumn_()).
var APP_HEADERS = [
  'applicationId',
  'studentEmail',
  'semester',
  'status',
  'currentStep',
  'progress',
  'completedSteps',
  'formData',
  'requiredAnnexes',
  'lastSaved',
  'submittedAt',
  'createdAt',
  'annexProgress'
];

var STUDENT_HEADERS = [
  'email',
  'fullName',
  'studentId',
  'phone',
  'programme',
  'updatedAt'
];

// Sprint 4 — pre-provisioned reviewer roster. Unlike Students, rows here
// are NOT auto-created on login: identifyReviewer() throws if the email
// isn't present + active, so only people the faculty has added can sign in.
var REVIEWER_HEADERS = [
  'email',
  'fullName',
  'title',          // e.g. "Associate Professor"
  'specialization',  // free text, used later for the Sprint 5 recommendation engine
  'active',          // TRUE/FALSE
  'updatedAt'
];

// Sprint 4 — who is reviewing what. One row per (applicationId, reviewerEmail).
// Created for now by adminAssignReviewer() as a stand-in for the Sprint 5
// Coordinator "Assign Reviewers" UI.
var ASSIGNMENT_HEADERS = [
  'assignmentId',
  'applicationId',
  'reviewerEmail',
  'semester',
  'assignedAt',
  'dueDate',
  'status',   // Assigned | InProgress | Completed
  'notified'  // Sprint 7 — TRUE/FALSE, batched assignment-email tracking
];

// Sprint 4 — one row per submitted/drafted review. A reviewer can save a
// Draft repeatedly (autosave) but only one Submitted review per
// (applicationId, reviewerEmail) pair — enforced in submitReview().
var REVIEW_HEADERS = [
  'reviewId',
  'applicationId',
  'reviewerEmail',
  'semester',
  'sectionComments',  // JSON: { sectionId: commentText }
  'rubricScores',      // JSON: { criterionId: 1-5 }
  'overallScore',       // 0-100 weighted percentage
  'decision',            // '' | 'Approved' | 'Minor Revisions' | 'Major Revisions' | 'Rejected'
  'signature',            // typed full name, only set once Submitted
  'status',                // Draft | Submitted
  'submittedAt',
  'updatedAt'
];

// Sprint 5, #31 — one row per uploaded annex attachment. Files themselves
// live in Drive (one subfolder per applicationId); this sheet is just the
// metadata index so the client can list/delete without re-scanning Drive.
var SHEET_ANNEX_FILES = 'AnnexFiles';
var ANNEX_FILE_HEADERS = [
  'fileId',
  'applicationId',
  'annexId',
  'fileName',
  'driveFileId',
  'driveUrl',
  'mimeType',
  'sizeBytes',
  'uploadedBy',
  'uploadedAt'
];

/* ------------------------------------------------------------------
   WEB APP ENTRY
   ------------------------------------------------------------------ */

/**
 * Serves Index.html (Landing / Login / Dashboard / Wizard shell).
 * @param {Object} e
 * @returns {HtmlOutput}
 */

/**
 * Serves Index.html (Landing / Login / Dashboard / Wizard shell).
 * @param {Object} e
 * @returns {HtmlOutput}
 */
function doGet(e) {
  return HtmlService.createTemplateFromFile('Index')
    .evaluate()
    .setTitle('BioEthics Portal | Faculty of Biotechnology, MSA University')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

/**
 * Template include helper: <?!= include('Stylesheet'); ?>
 * @param {string} filename
 * @returns {string}
 */
function include(filename) {
  return HtmlService.createHtmlOutputFromFile(filename).getContent();
}

/**
 * Manual one-time setup (optional). Run from the Apps Script editor
 * if you want to create/open the spreadsheet before the first login.
 * @returns {string} Spreadsheet URL
 */
function setupBioEthicsSheets() {
  var ss = ensureSpreadsheet_();
  return ss.getUrl();
}

/**
 * Returns the linked spreadsheet URL (empty string if not created yet).
 * @returns {string}
 */
function getSpreadsheetUrl() {
  var id = PropertiesService.getScriptProperties().getProperty(PROP_SPREADSHEET_ID);
  if (!id) return '';
  try {
    return SpreadsheetApp.openById(id).getUrl();
  } catch (err) {
    return '';
  }
}

function ensureSpreadsheet_() {
  var props = PropertiesService.getScriptProperties();
  var id = props.getProperty(PROP_SPREADSHEET_ID);
  var ss;

  if (id) {
    try {
      ss = SpreadsheetApp.openById(id);
    } catch (err) {
      ss = null;
    }
  }

  if (!ss) {
    ss = SpreadsheetApp.create('BioEthics Portal — Data');
    props.setProperty(PROP_SPREADSHEET_ID, ss.getId());
  }

  ensureSheetWithHeaders_(ss, SHEET_CONFIG, ['key', 'value']);
  ensureSheetWithHeaders_(ss, SHEET_STUDENTS, STUDENT_HEADERS);
  ensureSheetWithHeaders_(ss, SHEET_APPLICATIONS, APP_HEADERS);
  ensureAnnexProgressColumn_(ss); // Sprint 3 migration for pre-existing Sprint 2 sheets
  ensureSheetWithHeaders_(ss, SHEET_REVIEWERS, REVIEWER_HEADERS);   // Sprint 4
  ensureSheetWithHeaders_(ss, SHEET_ASSIGNMENTS, ASSIGNMENT_HEADERS); // Sprint 4
  ensureAssignmentNotifiedColumn_(ss); // Sprint 7 — migration for existing sheets
  ensureSheetWithHeaders_(ss, SHEET_REVIEWS, REVIEW_HEADERS);         // Sprint 4
  ensureSheetWithHeaders_(ss, SHEET_ANNEX_FILES, ANNEX_FILE_HEADERS); // Sprint 5, #31
  ensureSheetWithHeaders_(ss, SHEET_COORDINATORS, COORDINATOR_HEADERS); // Sprint 5 — Coordinator Portal
ensureArchiveSheet_(ss); // Sprint 6 — Automation (archive completed applications)
  var config = ss.getSheetByName(SHEET_CONFIG);
  if (config.getLastRow() < 2) {
    config.getRange(2, 1, 1, 2).setValues([['CurrentSemester', DEFAULT_SEMESTER]]);
  }

  // Remove default "Sheet1" if still empty leftover
  var leftover = ss.getSheetByName('Sheet1');
  if (leftover && ss.getSheets().length > 1) {
    try { ss.deleteSheet(leftover); } catch (e) { /* ignore */ }
  }

  return ss;
}

function ensureSheetWithHeaders_(ss, name, headers) {
  var sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
  }
  var existing = sheet.getRange(1, 1, 1, headers.length).getValues()[0];
  var needsHeader = !existing[0];
  if (needsHeader) {
    sheet.getRange(1, 1, 1, headers.length).setValues([headers]);
    sheet.setFrozenRows(1);
  }
  return sheet;
}

/**
 * Sprint 3 migration: if an Applications sheet was created by Sprint 2
 * (11 columns, no 'annexProgress'), add the 13th header + backfill
 * empty JSON objects so existing rows keep working with the new code.
 * Safe to call every time; it's a no-op once migrated.
 */
function ensureAnnexProgressColumn_(ss) {
  var sheet = ss.getSheetByName(SHEET_APPLICATIONS);
  if (!sheet) return;

  var headerRange = sheet.getRange(1, 1, 1, Math.max(sheet.getLastColumn(), APP_HEADERS.length));
  var headers = headerRange.getValues()[0];
  var col = APP_HEADERS.indexOf('annexProgress') + 1; // 1-based

  if (String(headers[col - 1] || '') === 'annexProgress') return; // already migrated

  sheet.getRange(1, col).setValue('annexProgress');
  var last = sheet.getLastRow();
  if (last >= 2) {
    var existing = sheet.getRange(2, col, last - 1, 1).getValues();
    var filled = existing.map(function (row) { return [row[0] ? row[0] : JSON.stringify({})]; });
    sheet.getRange(2, col, last - 1, 1).setValues(filled);
  }
}
/**
 * Sprint 7 migration: adds the 'notified' column to a pre-existing
 * Assignments sheet and backfills existing rows as already-notified
 * (TRUE) so turning this feature on doesn't suddenly email reviewers
 * about assignments they already know about.
 */
function ensureAssignmentNotifiedColumn_(ss) {
  var sheet = ss.getSheetByName(SHEET_ASSIGNMENTS);
  if (!sheet) return;
  var headerRange = sheet.getRange(1, 1, 1, Math.max(sheet.getLastColumn(), ASSIGNMENT_HEADERS.length));
  var headers = headerRange.getValues()[0];
  var col = ASSIGNMENT_HEADERS.indexOf('notified') + 1;
  if (String(headers[col - 1] || '') === 'notified') return;

  sheet.getRange(1, col).setValue('notified');
  var last = sheet.getLastRow();
  if (last >= 2) {
    var filled = [];
    for (var i = 0; i < last - 1; i++) filled.push(['TRUE']);
    sheet.getRange(2, col, last - 1, 1).setValues(filled);
  }
}

function getSheet_(name) {
  var ss = ensureSpreadsheet_();
  var sheet = ss.getSheetByName(name);
  if (!sheet) throw new Error('Missing sheet: ' + name);
  return sheet;
}

function getCurrentSemester_() {
  var sheet = getSheet_(SHEET_CONFIG);
  var data = sheet.getDataRange().getValues();
  for (var i = 1; i < data.length; i++) {
    if (String(data[i][0]) === 'CurrentSemester' && data[i][1]) {
      return String(data[i][1]);
    }
  }
  return DEFAULT_SEMESTER;
}

function safeParseJson_(value, fallback) {
  if (value && typeof value === 'object') return value;
  if (!value) return fallback;
  try {
    return JSON.parse(String(value));
  } catch (err) {
    return fallback;
  }
}

function countWords_(text) {
  var t = String(text || '').trim();
  if (!t) return 0;
  return t.split(/\s+/).filter(Boolean).length;
}

function isValidUniversityEmail_(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(email || ''));
}

function guessDisplayName_(email) {
  var local = String(email).split('@')[0] || 'Student';
  return local.replace(/[._-]+/g, ' ').replace(/\b\w/g, function (c) {
    return c.toUpperCase();
  });
}

function formatDisplayDate_(iso) {
  if (!iso) return '—';
  try {
    var d = new Date(iso);
    return Utilities.formatDate(d, Session.getScriptTimeZone() || 'Africa/Cairo', 'MMMM d, yyyy');
  } catch (err) {
    return String(iso);
  }
}

function describeNextAction_(status, currentStep, completed) {
  if (status === 'Submitted') {
    return 'Your application is submitted. Await committee review.';
  }
  var labels = {
    1: 'Complete Student Information',
    2: 'Complete Project Information',
    3: 'Complete Project Description',
    4: 'Complete Ethics Screening',
    5: 'Complete Risk Assessment',
    6: 'Review your application preview',
    7: 'Submit your application'
  };
  var step = currentStep || 1;
  for (var i = 1; i <= 7; i++) {
    if (completed.indexOf(i) === -1) {
      step = i;
      break;
    }
  }
  return labels[step] || 'Continue your application';
}

/**
 * CORE — Validation
 * Form/annex/review validation and score computation, shared by
 * both the Application and Reviewer services.
 */

/**
 * Maps ethics screening checkboxes → mandatory annex labels.
 * Stored on draft so a later annex-upload sprint can enforce them.
 */
function computeRequiredAnnexes_(flags) {
  var map = {
    'Human Participants': 'Annex II',
    'Human Samples': 'Annex III',
    'Animal Tissue': 'Annex IV',
    'Microorganisms': 'Annex V',
    'Cell Culture': 'Annex V',
    'Natural Extracts': 'Annex VI',
    'Hazardous Chemicals': 'Annex VII',
    'Ionizing Radiation': 'Annex VIII',
    '3D Printing': 'Annex IX',
    'Artificial Intelligence': 'Annex X',
    'Environmental Samples': 'Annex XI',
    'Clinical Data': 'Annex III',
    'Survey Data': 'Annex XII'
  };

  var out = [];
  var seen = {};
  (flags || []).forEach(function (flag) {
    var annex = map[flag];
    if (annex && !seen[annex]) {
      seen[annex] = true;
      out.push(annex);
    }
  });
  out.sort();
  return out;
}

function validateForSubmit_(form, completedSteps) {
  var errors = [];
  var needed = [1, 2, 3, 4, 5];
  needed.forEach(function (n) {
    if (completedSteps.indexOf(n) === -1) {
      errors.push('Step ' + n + ' is incomplete.');
    }
  });

  if (!form.studentId) errors.push('Student ID is required.');
  if (!isValidUniversityEmail_(form.universityEmail)) errors.push('A valid university email is required.');
  if (!form.phone) errors.push('Phone number is required.');
  if (!form.projectTitle) errors.push('Project title is required.');
  if (!form.purposeOfResearch) errors.push('Purpose of research is required.');
  if (!form.startDate || !form.endDate) errors.push('Project dates are required.');
  if (countWords_(form.background) < 50) errors.push('Background must be at least 50 words.');
  if (countWords_(form.researchAim) < 20) errors.push('Research aim must be at least 20 words.');
  if (countWords_(form.methodology) < 80) errors.push('Methodology must be at least 80 words.');
  errors = errors.concat(validateConditionalAnswers_(form.ethicsFlags || [], form.conditional || {}));
  return errors;
}

/**
 * SPRINT 3 — Server-side mirror of the client's conditional-question
 * gate: every screening flag the student checked must have its
 * required follow-up fields answered before the wizard (or final
 * submit) will accept Step 4 as complete.
 */
function validateConditionalAnswers_(flags, conditionalAnswers) {
  var errors = [];
  (flags || []).forEach(function (flag) {
    var questions = CONDITIONAL_QUESTIONS[flag];
    if (!questions) return;
    var answers = conditionalAnswers[flag] || {};
    questions.forEach(function (q) {
      if (!q.required) return;
      var val = answers[q.id];
      if (q.type === 'checkbox') {
        if (!val) errors.push('"' + q.label + '" must be confirmed for ' + flag + '.');
      } else if (q.type === 'textarea' && q.minWords) {
        if (countWords_(val) < q.minWords) errors.push('"' + q.label + '" needs at least ' + q.minWords + ' words.');
      } else if (!String(val || '').trim()) {
        errors.push('"' + q.label + '" is required for ' + flag + '.');
      }
    });
  });
  return errors;
}

/**
 * SPRINT 3 — Blocks final submission until every required annex's
 * checklist is fully ticked.
 */
function validateAnnexCompletion_(requiredAnnexes, progress) {
  var errors = [];
  var cards = buildAnnexCards_(requiredAnnexes, progress);
  cards.forEach(function (card) {
    if (!card.complete) {
      errors.push('Annex checklist incomplete: ' + card.title + ' (' + card.doneCount + '/' + card.totalCount + '). Open the Annex Dashboard to finish it.');
    }
  });
  return errors;
}

function validateReviewForSubmit_(rubricScores, decision, signature, certified) {
  var errors = [];
  REVIEW_RUBRIC.forEach(function (c) {
    var mark = rubricScores[c.id];
    if (mark === undefined || mark === null || mark === '' || isNaN(Number(mark)) || Number(mark) < 0 || Number(mark) > c.maxPoints) {
      errors.push('Please enter a valid mark (0–' + c.maxPoints + ') for every rubric criterion before submitting (missing/invalid: ' + c.label + ').');
    }
  });
  var validDecisions = ['Approved', 'Minor Revisions', 'Major Revisions', 'Rejected'];
  if (validDecisions.indexOf(decision) === -1) {
    errors.push('Please select a decision (Approve, Minor/Major Revisions, or Reject).');
  }
  if (!signature) {
    errors.push('A typed signature is required to submit a review.');
  }
  if (!certified) {
    errors.push('Please certify that this review reflects your independent assessment.');
  }
  return errors;
}

/**
 * Weighted average of 1-5 rubric scores, scaled to a 0-100 percentage.
 * Criteria that haven't been scored yet are simply excluded from the
 * running total (so a partially-filled rubric still shows a live
 * preview score while a reviewer is working).
 * @param {Object} rubricScores - { criterionId: 1-5 }
 * @returns {number}
 */
function computeOverallScore_(rubricScores) {
  // Sprint 7 — matches the official rubric: reviewers enter a numeric mark
  // per category (capped at that category's maxPoints), summed to a grade
  // out of 5. No longer a 1-5-star percentage.
  var total = 0;
  REVIEW_RUBRIC.forEach(function (c) {
    var mark = Number(rubricScores[c.id]);
    if (isNaN(mark) || mark < 0) return;
    total += Math.min(mark, c.maxPoints);
  });
  return Math.round(total * 100) / 100; // e.g. 3.75
}

/**
 * ANNEX FILES SERVICE — Sprint 5, #31 (file uploads, annex-scoped)
 * ------------------------------------------------------------------
 * Lets a student attach supporting documents to a specific required
 * annex on their own application (e.g. an SDS for Annex VII, a
 * consent form template for Annex II). Files upload through
 * google.script.run as base64, so there's a practical size cap
 * (MAX_UPLOAD_BYTES) — see the comment on that constant for why.
 *
 * Storage: one Drive folder per applicationId, inside a single
 * "BioEthics Portal Uploads" root folder. Metadata lives in the
 * AnnexFiles sheet (see 00_Core_Bootstrap.gs for schema/registration).
 *
 * Ownership: every function re-derives identity via identifyStudent()
 * (session-priority, same pattern as every other student-facing
 * function in this project) and then checks the caller actually owns
 * applicationId before touching anything.
 * ------------------------------------------------------------------
 */

// google.script.run has no officially documented hard byte limit (unlike
// DriveApp.createFile's 50MB), but real-world reports show large payloads
// through it get slow and unreliable well before that. 5MB raw (~6.7MB
// once base64-encoded) is a conservative, safely-inside-that-range cap.
var MAX_UPLOAD_BYTES = 5 * 1024 * 1024;

var ANNEX_FILE_LOCKED_STATUSES = ['Submitted', 'Under Review', 'Approved', 'Rejected'];

function getOrCreateUploadsRootFolder_() {
  var props = PropertiesService.getScriptProperties();
  var rootId = props.getProperty('ANNEX_UPLOADS_ROOT_FOLDER_ID');
  if (rootId) {
    try {
      return DriveApp.getFolderById(rootId);
    } catch (e) {
      // Folder was deleted/moved out of reach — fall through and recreate.
    }
  }
  var root = DriveApp.createFolder('BioEthics Portal Uploads');
  props.setProperty('ANNEX_UPLOADS_ROOT_FOLDER_ID', root.getId());
  return root;
}

function getOrCreateApplicationUploadFolder_(applicationId) {
  var root = getOrCreateUploadsRootFolder_();
  var existing = root.getFoldersByName(applicationId);
  if (existing.hasNext()) return existing.next();
  return root.createFolder(applicationId);
}

// Confirms the application exists, belongs to `email`, and returns its row
// data (so callers can also check status for the locked-application guard).
function assertOwnsApplication_(email, applicationId) {
  var found = findApplicationRowById_(applicationId);
  if (!found) throw new Error('Application not found.');
  var ownerEmail = String(found.values[1] || '').toLowerCase();
  if (ownerEmail !== email) throw new Error('You do not have access to this application.');
  return found;
}

function assertApplicationEditable_(found) {
  var status = String(found.values[3] || '');
  if (ANNEX_FILE_LOCKED_STATUSES.indexOf(status) !== -1) {
    throw new Error('This application is read-only — attachments cannot be added or removed.');
  }
}

function uploadAnnexFile(emailFromClient, applicationId, annexId, fileName, mimeType, base64Data) {
  var identity = identifyStudent(emailFromClient);
  var email = identity.email;
  var found = assertOwnsApplication_(email, applicationId);
  assertApplicationEditable_(found);

  if (!fileName || !base64Data) {
    throw new Error('No file data received — try selecting the file again.');
  }

  var decoded;
  try {
    decoded = Utilities.base64Decode(base64Data);
  } catch (e) {
    throw new Error('Could not read that file — try a different one.');
  }

  var sizeBytes = decoded.length;
  if (sizeBytes === 0) {
    throw new Error('That file appears to be empty.');
  }
  if (sizeBytes > MAX_UPLOAD_BYTES) {
    throw new Error('File is too large — maximum upload size is ' + Math.round(MAX_UPLOAD_BYTES / (1024 * 1024)) + ' MB.');
  }

  var blob = Utilities.newBlob(decoded, mimeType || 'application/octet-stream', fileName);
  var folder = getOrCreateApplicationUploadFolder_(applicationId);
  var driveFile = folder.createFile(blob);

  var fileId = 'FILE-' + Utilities.getUuid();
  var uploadedAt = new Date().toISOString();
  var sheet = getSheet_(SHEET_ANNEX_FILES);
  sheet.appendRow([
    fileId,
    applicationId,
    annexId || '',
    fileName,
    driveFile.getId(),
    driveFile.getUrl(),
    mimeType || 'application/octet-stream',
    sizeBytes,
    email,
    uploadedAt
  ]);

  return {
    fileId: fileId,
    annexId: annexId || '',
    fileName: fileName,
    driveUrl: driveFile.getUrl(),
    mimeType: mimeType || 'application/octet-stream',
    sizeBytes: sizeBytes,
    uploadedAt: uploadedAt
  };
}

function getAnnexFiles(emailFromClient, applicationId) {
  var identity = identifyStudent(emailFromClient);
  var email = identity.email;
  assertOwnsApplication_(email, applicationId); // read access — no editability check, files stay visible when locked

  var sheet = getSheet_(SHEET_ANNEX_FILES);
  var last = sheet.getLastRow();
  if (last < 2) return [];

  var values = sheet.getRange(2, 1, last - 1, ANNEX_FILE_HEADERS.length).getValues();
  var out = [];
  for (var i = 0; i < values.length; i++) {
    var row = values[i];
    if (String(row[1]) !== applicationId) continue;
    out.push({
      fileId: row[0],
      applicationId: row[1],
      annexId: row[2],
      fileName: row[3],
      driveUrl: row[5],
      mimeType: row[6],
      sizeBytes: row[7],
      uploadedBy: row[8],
      uploadedAt: row[9]
    });
  }
  return out;
}

function deleteAnnexFile(emailFromClient, applicationId, fileId) {
  var identity = identifyStudent(emailFromClient);
  var email = identity.email;
  var found = assertOwnsApplication_(email, applicationId);
  assertApplicationEditable_(found);

  var sheet = getSheet_(SHEET_ANNEX_FILES);
  var last = sheet.getLastRow();
  if (last < 2) throw new Error('File not found.');

  var values = sheet.getRange(2, 1, last - 1, ANNEX_FILE_HEADERS.length).getValues();
  for (var i = 0; i < values.length; i++) {
    if (String(values[i][0]) === fileId && String(values[i][1]) === applicationId) {
      var driveFileId = values[i][4];
      try {
        DriveApp.getFileById(driveFileId).setTrashed(true);
      } catch (e) {
        // Drive file already gone — still clean up the metadata row below.
      }
      sheet.deleteRow(i + 2);
      return { deleted: true, fileId: fileId };
    }
  }
  throw new Error('File not found.');
}

/**
 * APPLICATION SERVICE — Student wizard, dashboard, annex tracking
 * Everything a signed-in student touches: identify, dashboard data,
 * draft/submit application, annex progress.
 */

/**
 * Soft identity for Sprint 2: prefer the signed-in Google account,
 * otherwise accept the email from the login form. Password auth is
 * still deferred — the portal accepts the email as the working identity.
 *
 * @param {string} emailFromClient
 * @returns {{email:string, semester:string, displayName:string}}
 */
function identifyStudent(emailFromClient) {
  var sessionEmail = '';
  try {
    sessionEmail = Session.getActiveUser().getEmail() || '';
  } catch (err) {
    sessionEmail = '';
  }

  var email = String(emailFromClient || sessionEmail || '').trim().toLowerCase();
  if (!email || email.indexOf('@') === -1) {
    throw new Error('A valid university email is required.');
  }

  ensureSpreadsheet_();
  upsertStudentStub_(email);

  return {
    email: email,
    semester: getCurrentSemester_(),
    displayName: guessDisplayName_(email)
  };
}

/**
 * Dashboard snapshot for the signed-in student (current semester).
 * Creates nothing unless an application already exists.
 *
 * @param {string} email
 * @returns {Object}
 */
function getMyDashboardData(email) {
  var identity = identifyStudent(email);
  var app = findApplication_(identity.email, identity.semester);

  if (!app) {
    return {
      email: identity.email,
      studentName: identity.displayName,
      semester: identity.semester,
      hasApplication: false,
      applicationId: null,
      status: 'None',
      progress: 0,
      projectTitle: '—',
      supervisor: '—',
      lastUpdated: '—',
      currentStep: 0,
      completedSteps: [],
      nextAction: 'Start your ethics application for ' + identity.semester + '.'
    };
  }

  var form = safeParseJson_(app.formData, {});
  var completed = safeParseJson_(app.completedSteps, []);
  var progress = Number(app.progress) || 0;

  return {
    email: identity.email,
    studentName: form.fullName || identity.displayName,
    semester: identity.semester,
    hasApplication: true,
    applicationId: app.applicationId,
    status: app.status,
    progress: progress,
    projectTitle: form.projectTitle || 'Untitled project',
    supervisor: form.internalSupervisor || '—',
    lastUpdated: formatDisplayDate_(app.lastSaved),
    currentStep: Number(app.currentStep) || 1,
    completedSteps: completed,
    nextAction: describeNextAction_(app.status, Number(app.currentStep) || 1, completed)
  };
}

/**
 * Sprint 5 (item 1 — Navigation): every application row this student has
 * ever had, across all semesters, for the new "My Applications" /
 * "Draft Applications" / "Submitted Applications" pages. The one-row-per
 * (student, semester) rule from Sprint 2 is unchanged — this just stops
 * scoping the query to the *current* semester the way getMyDashboardData
 * does, so a student's history is visible once a new semester starts.
 *
 * @param {string} email
 * @returns {Object[]} newest-first
 */
function getMyApplications(email) {
  var identity = identifyStudent(email);
  var sheet = getSheet_(SHEET_APPLICATIONS);
  var last = sheet.getLastRow();
  if (last < 2) return [];

  var values = sheet.getRange(2, 1, last - 1, APP_HEADERS.length).getValues();
  var emailLc = identity.email.toLowerCase();
  var out = [];

  for (var i = 0; i < values.length; i++) {
    if (String(values[i][1]).toLowerCase() !== emailLc) continue;
    var app = rowToApp_(values[i]);
    var form = safeParseJson_(app.formData, {});
    out.push({
      applicationId: app.applicationId,
      semester: app.semester,
      status: app.status,
      progress: Number(app.progress) || 0,
      projectTitle: form.projectTitle || 'Untitled project',
      lastUpdated: formatDisplayDate_(app.lastSaved),
      lastSavedIso: app.lastSaved || '',
      submittedAt: app.submittedAt || ''
    });
  }

  out.sort(function (a, b) {
    return String(b.lastSavedIso).localeCompare(String(a.lastSavedIso));
  });
  return out;
}

/**
 * Sprint 5, item 2 — the one and only way a student can see anything
 * about a review. Deliberately strips reviewer identity, rubric scores,
 * and the overall percentage server-side (not just hidden in the UI) so
 * there is no code path in the student surface that can leak marks —
 * see item 6. Only a *Submitted* review counts as a decision; a
 * reviewer's in-progress Draft is never visible to the student it's
 * about.
 *
 * @param {string} email
 * @param {string} applicationId
 * @returns {Object} { hasDecision, status, decision, comments, decidedAt }
 */
function getApplicationDecision(email, applicationId) {
  var identity = identifyStudent(email);
  var appRow = findApplicationRowById_(applicationId);
  if (!appRow) throw new Error('Application not found.');
  var app = rowToApp_(appRow.values);
  if (String(app.studentEmail).toLowerCase() !== identity.email.toLowerCase()) {
    throw new Error('You do not have access to this application.');
  }

  var review = findSubmittedReviewForApplication_(applicationId);
  if (!review) {
    return {
      hasDecision: false,
      status: app.status,
      decision: '',
      comments: [],
      decidedAt: ''
    };
  }

  var sectionComments = safeParseJson_(review.sectionComments, {});
  var comments = REVIEW_SECTIONS.map(function (section) {
    return { section: section.title, comment: sectionComments[section.id] || '' };
  }).filter(function (c) { return c.comment; });

  return {
    hasDecision: true,
    status: app.status,
    decision: review.decision || '',
    comments: comments, // no reviewerEmail, rubricScores, or overallScore included — by design
    decidedAt: formatDisplayDate_(review.submittedAt)
  };
}

/**
 * First Submitted review found for an application, regardless of which
 * reviewer wrote it — students never learn reviewer identity, so the
 * caller (getApplicationDecision) can't and shouldn't select "by
 * reviewer". Single-reviewer decision model per Sprint 4 §4.6.
 */
function findSubmittedReviewForApplication_(applicationId) {
  var sheet = getSheet_(SHEET_REVIEWS);
  var last = sheet.getLastRow();
  if (last < 2) return null;
  var values = sheet.getRange(2, 1, last - 1, REVIEW_HEADERS.length).getValues();
  for (var i = 0; i < values.length; i++) {
    var review = rowToReview_(values[i]);
    if (String(review.applicationId) === String(applicationId) && review.status === 'Submitted') {
      return review;
    }
  }
  return null;
}

/**
 * Load (or lazily create) the student's one application for the semester.
 * Enforces ONE application per studentEmail + semester.
 *
 * @param {string} email
 * @returns {Object} Application DTO for the wizard
 */
function getOrCreateMyApplication(email) {
  var identity = identifyStudent(email);
  var app = findApplication_(identity.email, identity.semester);

  if (!app) {
    app = createDraftApplication_(identity.email, identity.semester);
  }

  return serializeApplication_(app);
}

/**
 * Persist a draft. Rejects if an app is already Submitted
 * (students cannot reopen in Sprint 2).
 *
 * @param {string} email
 * @param {Object} payload - { applicationId, currentStep, completedSteps, formData, progress }
 * @returns {Object} Updated application DTO
 */
function saveDraft(email, payload) {
  var identity = identifyStudent(email);
  ensureSpreadsheet_();

  var sheet = getSheet_(SHEET_APPLICATIONS);
  var rowInfo = findApplicationRow_(identity.email, identity.semester);

  if (!rowInfo) {
    throw new Error('No application found. Open the wizard again to create a draft.');
  }

  var existing = rowToApp_(rowInfo.values);
  if (String(existing.status) === 'Submitted') {
    throw new Error('This application has already been submitted and can no longer be edited.');
  }

  if (payload.applicationId && payload.applicationId !== existing.applicationId) {
    throw new Error('Application ID mismatch.');
  }

  var now = new Date().toISOString();
  var formData = payload.formData || safeParseJson_(existing.formData, {});
  var completedSteps = payload.completedSteps || safeParseJson_(existing.completedSteps, []);
  var currentStep = Number(payload.currentStep) || Number(existing.currentStep) || 1;
  var progress = Number(payload.progress);
  if (isNaN(progress)) progress = Number(existing.progress) || 0;

  var requiredAnnexes = computeRequiredAnnexes_(formData.ethicsFlags || []);

  var next = [
    existing.applicationId,
    identity.email,
    identity.semester,
    'Draft',
    currentStep,
    progress,
    JSON.stringify(completedSteps),
    JSON.stringify(formData),
    JSON.stringify(requiredAnnexes),
    now,
    existing.submittedAt || '',
    existing.createdAt || now,
    reconcileAnnexProgress_(existing.annexProgress, requiredAnnexes) // Sprint 3
  ];

  sheet.getRange(rowInfo.row, 1, 1, APP_HEADERS.length).setValues([next]);
  syncStudentFromForm_(identity.email, formData);

  return serializeApplication_(rowToApp_(next));
}

/**
 * Final submit. Validates completeness server-side, then locks status.
 *
 * @param {string} email
 * @param {Object} payload
 * @returns {Object}
 */
function submitApplication(email, payload) {
  var identity = identifyStudent(email);
  var draft = saveDraft(email, payload);

  var form = draft.formData || {};
  var requiredAnnexes = computeRequiredAnnexes_(form.ethicsFlags || []);
  var annexProgress = safeParseJson_(draft.annexProgress, {});

  var errors = validateForSubmit_(form, draft.completedSteps || []);
  errors = errors.concat(validateAnnexCompletion_(requiredAnnexes, annexProgress));
  if (errors.length) {
    throw new Error(errors[0]);
  }

  if (!form.declaration) {
    throw new Error('You must confirm the student declaration before submitting.');
  }

  var sheet = getSheet_(SHEET_APPLICATIONS);
  var rowInfo = findApplicationRow_(identity.email, identity.semester);
  var existing = rowToApp_(rowInfo.values);
  var now = new Date().toISOString();

  var next = [
    existing.applicationId,
    identity.email,
    identity.semester,
    'Submitted',
    7,
    100,
    JSON.stringify([1, 2, 3, 4, 5, 6, 7]),
    JSON.stringify(form),
    JSON.stringify(requiredAnnexes),
    now,
    now,
    existing.createdAt || now,
    JSON.stringify(annexProgress)
  ];

  sheet.getRange(rowInfo.row, 1, 1, APP_HEADERS.length).setValues([next]);

  // Sprint 6 — notify the student their application was submitted.
  // Never throws (see 06_Automation_Notifications.gs), so a mail
  // hiccup can never block a successful submission.
  notifyStudentStatusChange_(existing.applicationId, 'Submitted');

  return serializeApplication_(rowToApp_(next));
}
/**
 * SPRINT 3 — Annex Dashboard snapshot for the signed-in student.
 * Builds one card per annex the current screening answers require,
 * each with its checklist items and completion state.
 *
 * @param {string} email
 * @returns {Object}
 */
function getAnnexDashboard(email) {
  var identity = identifyStudent(email);
  var app = findApplication_(identity.email, identity.semester);

  if (!app) {
    return {
      applicationId: null,
      status: 'None',
      locked: true,
      overallPercent: 0,
      annexes: [],
      message: 'Start your ethics application first — the Annex Dashboard fills in once you complete Ethics Screening.'
    };
  }

  var form = safeParseJson_(app.formData, {});
  var requiredAnnexes = safeParseJson_(app.requiredAnnexes, []);
  var progress = safeParseJson_(app.annexProgress, {});
  var annexes = buildAnnexCards_(requiredAnnexes, progress);
  var overall = calcOverallAnnexPercent_(annexes);

  return {
    applicationId: app.applicationId,
    status: app.status,
    locked: String(app.status) === 'Submitted',
    ethicsFlags: form.ethicsFlags || [],
    overallPercent: overall,
    annexes: annexes,
    message: requiredAnnexes.length
      ? ''
      : 'No annexes are required yet. Complete Ethics Screening (Step 4) if your project involves any special conditions.'
  };
}

/**
 * SPRINT 3 — Persist annex checklist ticks + notes for one or more annexes.
 * Rejects edits once the application has been submitted.
 *
 * @param {string} email
 * @param {Object} progressPatch - { "Annex II": { items: {"0":true,...}, note: "..." }, ... }
 * @returns {Object} Same shape as getAnnexDashboard()
 */
function saveAnnexProgress(email, progressPatch) {
  var identity = identifyStudent(email);
  var rowInfo = findApplicationRow_(identity.email, identity.semester);
  if (!rowInfo) {
    throw new Error('No application found. Open the wizard first to create a draft.');
  }

  var existing = rowToApp_(rowInfo.values);
  if (String(existing.status) === 'Submitted') {
    throw new Error('This application has already been submitted — the annex checklist is locked.');
  }

  var requiredAnnexes = safeParseJson_(existing.requiredAnnexes, []);
  var current = safeParseJson_(existing.annexProgress, {});
  var merged = mergeAnnexProgress_(current, progressPatch || {}, requiredAnnexes);

  var sheet = getSheet_(SHEET_APPLICATIONS);
  sheet.getRange(rowInfo.row, APP_HEADERS.indexOf('annexProgress') + 1).setValue(JSON.stringify(merged));
  sheet.getRange(rowInfo.row, APP_HEADERS.indexOf('lastSaved') + 1).setValue(new Date().toISOString());

  return getAnnexDashboard(email);
}

function findApplication_(email, semester) {
  var row = findApplicationRow_(email, semester);
  return row ? rowToApp_(row.values) : null;
}

function findApplicationRow_(email, semester) {
  var sheet = getSheet_(SHEET_APPLICATIONS);
  var last = sheet.getLastRow();
  if (last < 2) return null;

  var values = sheet.getRange(2, 1, last, APP_HEADERS.length).getValues();
  var emailLc = String(email).toLowerCase();
  var semesterLc = String(semester).toLowerCase();

  for (var i = 0; i < values.length; i++) {
    if (String(values[i][1]).toLowerCase() === emailLc &&
        String(values[i][2]).toLowerCase() === semesterLc) {
      return { row: i + 2, values: values[i] };
    }
  }
  return null;
}

function findApplicationRowById_(applicationId) {
  var sheet = getSheet_(SHEET_APPLICATIONS);
  var last = sheet.getLastRow();
  if (last < 2) return null;
  var values = sheet.getRange(2, 1, last - 1, APP_HEADERS.length).getValues();
  for (var i = 0; i < values.length; i++) {
    if (String(values[i][0]) === applicationId) return { row: i + 2, values: values[i] };
  }
  return null;
}

function createDraftApplication_(email, semester) {
  var sheet = getSheet_(SHEET_APPLICATIONS);
  var now = new Date().toISOString();
  var applicationId = buildApplicationId_(semester, email);
  var emptyForm = defaultFormData_(email);

  var row = [
    applicationId,
    email,
    semester,
    'Draft',
    1,
    0,
    JSON.stringify([]),
    JSON.stringify(emptyForm),
    JSON.stringify([]),
    now,
    '',
    now,
    JSON.stringify({}) // annexProgress — Sprint 3
  ];

  sheet.appendRow(row);
  return rowToApp_(row);
}

function rowToApp_(values) {
  var obj = {};
  for (var i = 0; i < APP_HEADERS.length; i++) {
    var v = values[i];
    obj[APP_HEADERS[i]] = (v instanceof Date) ? v.toISOString() : v;
  }
  return obj;
}

function serializeApplication_(app) {
  return {
    applicationId: app.applicationId,
    studentEmail: app.studentEmail,
    semester: app.semester,
    status: app.status,
    currentStep: Number(app.currentStep) || 1,
    progress: Number(app.progress) || 0,
    completedSteps: safeParseJson_(app.completedSteps, []),
    formData: safeParseJson_(app.formData, defaultFormData_(app.studentEmail)),
    requiredAnnexes: safeParseJson_(app.requiredAnnexes, []),
    annexProgress: safeParseJson_(app.annexProgress, {}),
    lastSaved: app.lastSaved || '',
    submittedAt: app.submittedAt || '',
    createdAt: app.createdAt || ''
  };
}

function defaultFormData_(email) {
  return {
    fullName: '',
    studentId: '',
    universityEmail: email || '',
    phone: '',
    faculty: 'Biotechnology',
    programme: '',
    hostInstitution: 'MSA University',
    internalSupervisor: '',
    externalSupervisor: '',
    projectTitle: '',
    purposeOfResearch: '',
    researchCategory: '',
    hostInstitutions: 'MSA University',
    startDate: '',
    endDate: '',
    background: '',
    researchAim: '',
    methodology: '',
    ethicsFlags: [],
    conditional: {}, // Sprint 3 — dynamic follow-up answers keyed by ethicsFlag
    hazards: [],
    declaration: false
  };
}

function upsertStudentStub_(email) {
  var sheet = getSheet_(SHEET_STUDENTS);
  var last = sheet.getLastRow();
  var now = new Date().toISOString();

  if (last >= 2) {
    var data = sheet.getRange(2, 1, last, STUDENT_HEADERS.length).getValues();
    for (var i = 0; i < data.length; i++) {
      if (String(data[i][0]).toLowerCase() === email) {
        return;
      }
    }
  }

  sheet.appendRow([email, guessDisplayName_(email), '', '', '', now]);
}

function syncStudentFromForm_(email, form) {
  var sheet = getSheet_(SHEET_STUDENTS);
  var last = sheet.getLastRow();
  var now = new Date().toISOString();
  var row = [
    email,
    form.fullName || guessDisplayName_(email),
    form.studentId || '',
    form.phone || '',
    form.programme || '',
    now
  ];

  if (last >= 2) {
    var data = sheet.getRange(2, 1, last, STUDENT_HEADERS.length).getValues();
    for (var i = 0; i < data.length; i++) {
      if (String(data[i][0]).toLowerCase() === email) {
        sheet.getRange(i + 2, 1, 1, STUDENT_HEADERS.length).setValues([row]);
        return;
      }
    }
  }
  sheet.appendRow(row);
}

function buildApplicationId_(semester, email) {
  var year = (semester.match(/\d{4}/) || [new Date().getFullYear()])[0];
  var term = /spring/i.test(semester) ? 'SPR' : (/summer/i.test(semester) ? 'SUM' : 'FALL');
  var stamp = Utilities.formatDate(new Date(), Session.getScriptTimeZone() || 'Africa/Cairo', 'HHmmss');
  var suffix = Utilities.base64EncodeWebSafe(email).replace(/[^A-Za-z0-9]/g, '').slice(0, 4).toUpperCase();
  return 'BIO-' + year + '-' + term + '-' + suffix + stamp.slice(-3);
}

/**
 * SPRINT 3 — Builds the Annex Dashboard cards: one per required annex,
 * with each checklist item's done/undone state and a completion %.
 */
function buildAnnexCards_(requiredAnnexes, progress) {
  return (requiredAnnexes || []).map(function (annexId) {
    var checklist = ANNEX_CHECKLISTS[annexId] || [];
    var saved = (progress && progress[annexId]) || { items: {}, note: '' };
    var items = checklist.map(function (label, idx) {
      return { index: idx, label: label, done: !!saved.items[String(idx)] };
    });
    var doneCount = items.filter(function (it) { return it.done; }).length;
    var percent = items.length ? Math.round((doneCount / items.length) * 100) : 100;

    return {
      id: annexId,
      title: ANNEX_TITLES[annexId] || annexId,
      items: items,
      note: saved.note || '',
      doneCount: doneCount,
      totalCount: items.length,
      percent: percent,
      complete: items.length > 0 && doneCount === items.length
    };
  });
}

function calcOverallAnnexPercent_(annexCards) {
  if (!annexCards.length) return 100; // nothing required = nothing blocking
  var sum = annexCards.reduce(function (acc, a) { return acc + a.percent; }, 0);
  return Math.round(sum / annexCards.length);
}

/**
 * SPRINT 3 — Merge a partial save (one or more annexes) into the
 * full annexProgress object, dropping any annex that's no longer
 * required by the current screening answers.
 */
function mergeAnnexProgress_(current, patch, requiredAnnexes) {
  var merged = {};
  requiredAnnexes.forEach(function (annexId) {
    merged[annexId] = current[annexId] || { items: {}, note: '' };
  });
  Object.keys(patch).forEach(function (annexId) {
    if (requiredAnnexes.indexOf(annexId) === -1) return; // ignore stale/unrequired annex
    var incoming = patch[annexId] || {};
    var base = merged[annexId] || { items: {}, note: '' };
    merged[annexId] = {
      items: Object.assign({}, base.items, incoming.items || {}),
      note: incoming.note != null ? incoming.note : base.note
    };
  });
  return merged;
}

/**
 * SPRINT 3 — When a draft is saved, drop annex entries the student's
 * latest screening answers no longer require (keeps the sheet tidy)
 * while preserving progress on annexes that are still required.
 */
function reconcileAnnexProgress_(existingJson, requiredAnnexes) {
  var existing = safeParseJson_(existingJson, {});
  var kept = {};
  requiredAnnexes.forEach(function (annexId) {
    kept[annexId] = existing[annexId] || { items: {}, note: '' };
  });
  return JSON.stringify(kept);
}

function updateApplicationStatus_(applicationId, newStatus) {
  var appRow = findApplicationRowById_(applicationId);
  if (!appRow) return;
  var statusCol = APP_HEADERS.indexOf('status') + 1;
  getSheet_(SHEET_APPLICATIONS).getRange(appRow.row, statusCol).setValue(newStatus);
}

function decisionToApplicationStatus_(decision) {
  switch (decision) {
    case 'Approved': return 'Approved';
    case 'Rejected': return 'Rejected';
    case 'Minor Revisions':
    case 'Major Revisions':
      return 'Revision Requested';
    default: return 'Under Review';
  }
}

/**
 * REVIEWER SERVICE — Reviewer dashboard, assignments, review workflow
 * Everything a signed-in reviewer touches, plus the coordinator/admin
 * utility functions (adminRegisterReviewer / adminAssignReviewer) that
 * are meant to be run manually from the Apps Script editor.
 */

/**
 * Reviewer identity. Unlike identifyStudent(), this does NOT create a
 * new row on first login — the reviewer must already exist in the
 * Reviewers sheet with active = TRUE (added via adminRegisterReviewer(),
 * a stand-in for the Sprint 5 Coordinator "manage reviewers" screen).
 *
 * @param {string} emailFromClient
 * @returns {{email:string, displayName:string, title:string, semester:string}}
 */
function identifyReviewer(emailFromClient) {
  var sessionEmail = '';
  try {
    sessionEmail = Session.getActiveUser().getEmail() || '';
  } catch (err) {
    sessionEmail = '';
  }

  var email = String(emailFromClient || sessionEmail || '').trim().toLowerCase();
  if (!email || email.indexOf('@') === -1) {
    throw new Error('A valid university email is required.');
  }

  var row = findReviewerRow_(email);
  if (!row) {
    throw new Error('This email is not registered as a reviewer. Contact the Ethics Committee coordinator.');
  }
  var reviewer = rowToReviewer_(row.values);
  if (String(reviewer.active).toUpperCase() !== 'TRUE') {
    throw new Error('This reviewer account is inactive. Contact the Ethics Committee coordinator.');
  }

  return {
    email: reviewer.email,
    displayName: reviewer.fullName || guessDisplayName_(email),
    title: reviewer.title || '',
    semester: getCurrentSemester_()
  };
}

/**
 * Reviewer dashboard snapshot: assignment counts + the nearest deadlines.
 * @param {string} email
 * @returns {Object}
 */
function getReviewerDashboardData(email) {
  var identity = identifyReviewer(email);
  var assignments = listAssignmentsForReviewer_(identity.email);

  var assigned = 0, inProgress = 0, completed = 0;
  var upcoming = [];
  assignments.forEach(function (a) {
    if (a.status === 'Completed') completed++;
    else if (a.status === 'InProgress') inProgress++;
    else assigned++;
    if (a.status !== 'Completed') upcoming.push(a);
  });
  upcoming.sort(function (a, b) { return String(a.dueDate).localeCompare(String(b.dueDate)); });

  return {
    reviewerName: identity.displayName,
    title: identity.title,
    semester: identity.semester,
    totalAssigned: assignments.length,
    pendingCount: assigned + inProgress,
    inProgressCount: inProgress,
    completedCount: completed,
    nextDue: upcoming.length ? upcoming[0] : null
  };
}

/**
 * All applications assigned to this reviewer for the current semester,
 * joined with a compact application summary + this reviewer's own
 * review status (Draft/Submitted/none) for each.
 * @param {string} email
 * @returns {Object[]}
 */
function getAssignedApplications(email) {
  var identity = identifyReviewer(email);
  var assignments = listAssignmentsForReviewer_(identity.email);

  return assignments.map(function (a) {
    var appRow = findApplicationRowById_(a.applicationId);
    var app = appRow ? rowToApp_(appRow.values) : null;
    var form = app ? safeParseJson_(app.formData, {}) : {};
    var review = findReviewRow_(a.applicationId, identity.email);
    var reviewObj = review ? rowToReview_(review.values) : null;

    return {
      assignmentId: a.assignmentId,
      applicationId: a.applicationId,
      semester: a.semester,
      assignedAt: a.assignedAt,
      dueDate: a.dueDate,
      assignmentStatus: a.status,
      projectTitle: form.projectTitle || '(untitled project)',
      studentName: form.fullName || (app ? app.studentEmail : ''),
      applicationStatus: app ? app.status : 'Unknown',
      requiredAnnexes: app ? safeParseJson_(app.requiredAnnexes, []) : [],
      reviewStatus: reviewObj ? reviewObj.status : 'Not started',
      overallScore: reviewObj ? reviewObj.overallScore : null,
      decision: reviewObj ? reviewObj.decision : ''
    };
  });
}

/**
 * Full read-only application detail + this reviewer's in-progress (or
 * blank) review, for the section-by-section review screen. Throws if
 * this reviewer has no assignment for the application (prevents a
 * reviewer from opening someone else's assignment by guessing an ID).
 *
 * @param {string} email
 * @param {string} applicationId
 * @returns {Object}
 */
function getApplicationForReview(email, applicationId) {
  var identity = identifyReviewer(email);
  var assignment = findAssignment_(applicationId, identity.email);
  if (!assignment) {
    throw new Error('You are not assigned to review this application.');
  }

  var appRow = findApplicationRowById_(applicationId);
  if (!appRow) {
    throw new Error('Application not found.');
  }
  var app = rowToApp_(appRow.values);
  var review = findReviewRow_(applicationId, identity.email);
  var reviewObj = review ? rowToReview_(review.values) : blankReview_(applicationId, identity.email, app.semester);

  return {
    application: serializeApplication_(app),
    review: reviewObj,
    rubric: REVIEW_RUBRIC,
    sections: REVIEW_SECTIONS,
    annexTitles: ANNEX_TITLES,
    annexChecklists: ANNEX_CHECKLISTS
  };
}

/**
 * Autosave a review-in-progress. Never touches the application record
 * itself — reviewers cannot edit student data, only comment/score it.
 * @param {string} email
 * @param {string} applicationId
 * @param {Object} payload - { sectionComments, rubricScores }
 * @returns {Object} the saved review DTO
 */
function saveReviewDraft(email, applicationId, payload) {
  var identity = identifyReviewer(email);
  var assignment = findAssignment_(applicationId, identity.email);
  if (!assignment) {
    throw new Error('You are not assigned to review this application.');
  }

  var appRow = findApplicationRowById_(applicationId);
  if (!appRow) throw new Error('Application not found.');
  var app = rowToApp_(appRow.values);

  upsertReview_(applicationId, identity.email, app.semester, {
    sectionComments: payload && payload.sectionComments || {},
    rubricScores: payload && payload.rubricScores || {},
    overallScore: computeOverallScore_(payload && payload.rubricScores || {}),
    status: 'Draft'
  });

  if (assignment.status === 'Assigned') {
    setAssignmentStatus_(assignment.assignmentId, 'InProgress');
  }

  var saved = findReviewRow_(applicationId, identity.email);
  return rowToReview_(saved.values);
}

/**
 * Finalize a review: requires every rubric criterion scored, a decision,
 * and a typed signature + certification checkbox. Locks the review
 * (Draft -> Submitted, immutable after) and updates the parent
 * application's status to reflect the decision.
 *
 * Note: this is a single-reviewer decision model. Multi-reviewer
 * consensus / chair sign-off is Sprint 5 Coordinator Portal scope —
 * see PROJECT.md §7.
 *
 * @param {string} email
 * @param {string} applicationId
 * @param {Object} payload - { sectionComments, rubricScores, decision, signature, certified }
 * @returns {Object} the submitted review DTO
 */
function submitReview(email, applicationId, payload) {
  var identity = identifyReviewer(email);
  var assignment = findAssignment_(applicationId, identity.email);
  if (!assignment) {
    throw new Error('You are not assigned to review this application.');
  }

  var existingRow = findReviewRow_(applicationId, identity.email);
  if (existingRow) {
    var existing = rowToReview_(existingRow.values);
    if (existing.status === 'Submitted') {
      throw new Error('This review has already been submitted and cannot be changed.');
    }
  }

  var rubricScores = (payload && payload.rubricScores) || {};
  var decision = String((payload && payload.decision) || '').trim();
  var signature = String((payload && payload.signature) || '').trim();
  var certified = !!(payload && payload.certified);

  var errors = validateReviewForSubmit_(rubricScores, decision, signature, certified);
  if (errors.length) throw new Error(errors[0]);

  var appRow = findApplicationRowById_(applicationId);
  if (!appRow) throw new Error('Application not found.');
  var app = rowToApp_(appRow.values);

  var overallScore = computeOverallScore_(rubricScores);
  var now = new Date().toISOString();

  upsertReview_(applicationId, identity.email, app.semester, {
    sectionComments: (payload && payload.sectionComments) || {},
    rubricScores: rubricScores,
    overallScore: overallScore,
    decision: decision,
    signature: signature,
    status: 'Submitted',
    submittedAt: now
  });

  setAssignmentStatus_(assignment.assignmentId, 'Completed');
  updateApplicationStatus_(applicationId, decisionToApplicationStatus_(decision));

  // Sprint 6 — notify the student of the decision (Approved / Rejected /
  // Revision Requested). Never throws — see 06_Automation_Notifications.gs.
  notifyStudentStatusChange_(applicationId, decisionToApplicationStatus_(decision));

  var saved = findReviewRow_(applicationId, identity.email);
  return rowToReview_(saved.values);
}

/**
 * All reviews (Draft + Submitted) this reviewer has ever produced,
 * newest first — used by the "Review History" screen.
 * @param {string} email
 * @returns {Object[]}
 */
function getReviewHistory(email) {
  var identity = identifyReviewer(email);
  var sheet = getSheet_(SHEET_REVIEWS);
  var last = sheet.getLastRow();
  if (last < 2) return [];

  var values = sheet.getRange(2, 1, last - 1, REVIEW_HEADERS.length).getValues();
  var emailLc = identity.email.toLowerCase();
  var out = [];

  values.forEach(function (row) {
    var review = rowToReview_(row);
    if (String(review.reviewerEmail).toLowerCase() !== emailLc) return;

    var appRow = findApplicationRowById_(review.applicationId);
    var form = appRow ? safeParseJson_(rowToApp_(appRow.values).formData, {}) : {};
    out.push({
      applicationId: review.applicationId,
      projectTitle: form.projectTitle || '(untitled project)',
      studentName: form.fullName || '',
      status: review.status,
      decision: review.decision,
      overallScore: review.overallScore,
      submittedAt: review.submittedAt,
      updatedAt: review.updatedAt
    });
  });

  out.sort(function (a, b) {
    return String(b.updatedAt || '').localeCompare(String(a.updatedAt || ''));
  });
  return out;
}

/**
 * Admin utility (stand-in for the Sprint 5 Coordinator "manage
 * reviewers" screen): add or reactivate a reviewer. Run this from the
 * Apps Script editor's function picker, or call it from a temporary
 * script — it is not wired to any UI yet.
 * @param {string} email
 * @param {string} fullName
 * @param {string} title
 * @param {string} specialization
 */
function adminRegisterReviewer(email, fullName, title, specialization) {
  email = String(email || '').trim().toLowerCase();
  if (!isValidUniversityEmail_(email)) throw new Error('Invalid email.');

  var sheet = getSheet_(SHEET_REVIEWERS);
  var now = new Date().toISOString();
  var row = [email, fullName || guessDisplayName_(email), title || '', specialization || '', 'TRUE', now];

  var existing = findReviewerRow_(email);
  if (existing) {
    sheet.getRange(existing.row, 1, 1, REVIEWER_HEADERS.length).setValues([row]);
  } else {
    sheet.appendRow(row);
  }
  return rowToReviewer_(row);
}

/**
 * Admin utility (stand-in for the Sprint 5 "Assign Reviewers" screen):
 * assign one reviewer to one submitted application. Moves the
 * application from Submitted -> Under Review the first time it gets an
 * assignment. Run from the Apps Script editor until Sprint 5 ships.
 * @param {string} applicationId
 * @param {string} reviewerEmail
 * @param {string} dueDateIso - optional ISO date string
 */
function adminAssignReviewer(applicationId, reviewerEmail, dueDateIso) {
  reviewerEmail = String(reviewerEmail || '').trim().toLowerCase();
  if (!findReviewerRow_(reviewerEmail)) {
    throw new Error('Unknown reviewer email — register them first with adminRegisterReviewer().');
  }
  var appRow = findApplicationRowById_(applicationId);
  if (!appRow) throw new Error('Application not found.');
  var app = rowToApp_(appRow.values);
  if (app.status === 'Draft') {
    throw new Error('Cannot assign a reviewer before the student submits the application.');
  }

  var sheet = getSheet_(SHEET_ASSIGNMENTS);
  var now = new Date().toISOString();
  var existing = findAssignment_(applicationId, reviewerEmail);

  if (!existing) {
    var assignmentId = 'ASG-' + Utilities.getUuid().slice(0, 8).toUpperCase();
    sheet.appendRow([assignmentId, applicationId, reviewerEmail, app.semester, now, dueDateIso || '', 'Assigned', 'FALSE']);
  }

  if (app.status === 'Submitted') {
    updateApplicationStatus_(applicationId, 'Under Review');
    // Sprint 6 — notify the student their application is now under
    // review. Never throws — see 06_Automation_Notifications.gs.
    notifyStudentStatusChange_(applicationId, 'Under Review');
  }

  // Sprint 7 — no automatic per-assignment email anymore. The reviewer
  // stays 'notified: FALSE' until the coordinator explicitly clicks
  // "Notify Reviewers" (see notifyPendingReviewerAssignments below),
  // which batches everything new into one email per reviewer.
}

function findReviewerRow_(email) {
  var sheet = getSheet_(SHEET_REVIEWERS);
  var last = sheet.getLastRow();
  if (last < 2) return null;
  var values = sheet.getRange(2, 1, last - 1, REVIEWER_HEADERS.length).getValues();
  var emailLc = String(email).trim().toLowerCase();
  for (var i = 0; i < values.length; i++) {
    if (String(values[i][0]).trim().toLowerCase() === emailLc) {
      return { row: i + 2, values: values[i] };
    }
  }
  return null;
}

function rowToReviewer_(values) {
  var obj = {};
  for (var i = 0; i < REVIEWER_HEADERS.length; i++) {
    var v = values[i];
    obj[REVIEWER_HEADERS[i]] = (v instanceof Date) ? v.toISOString() : v;
  }
  return obj;
}

function listAssignmentsForReviewer_(email) {
  var sheet = getSheet_(SHEET_ASSIGNMENTS);
  var last = sheet.getLastRow();
  if (last < 2) return [];
  var values = sheet.getRange(2, 1, last - 1, ASSIGNMENT_HEADERS.length).getValues();
  var emailLc = String(email).trim().toLowerCase();
  var out = [];
  values.forEach(function (row) {
    if (String(row[2]).trim().toLowerCase() === emailLc) out.push(rowToAssignment_(row));
  });
  return out;
}

function findAssignment_(applicationId, reviewerEmail) {
  var sheet = getSheet_(SHEET_ASSIGNMENTS);
  var last = sheet.getLastRow();
  if (last < 2) return null;
  var values = sheet.getRange(2, 1, last - 1, ASSIGNMENT_HEADERS.length).getValues();
  var emailLc = String(reviewerEmail).trim().toLowerCase();
  for (var i = 0; i < values.length; i++) {
    if (String(values[i][1]) === applicationId && String(values[i][2]).trim().toLowerCase() === emailLc) {
      var obj = rowToAssignment_(values[i]);
      obj.row = i + 2;
      return obj;
    }
  }
  return null;
}

function setAssignmentStatus_(assignmentId, status) {
  var sheet = getSheet_(SHEET_ASSIGNMENTS);
  var last = sheet.getLastRow();
  if (last < 2) return;
  var values = sheet.getRange(2, 1, last - 1, ASSIGNMENT_HEADERS.length).getValues();
  for (var i = 0; i < values.length; i++) {
    if (String(values[i][0]) === assignmentId) {
      sheet.getRange(i + 2, ASSIGNMENT_HEADERS.indexOf('status') + 1).setValue(status);
      return;
    }
  }
}

function rowToAssignment_(values) {
  var obj = {};
  for (var i = 0; i < ASSIGNMENT_HEADERS.length; i++) {
    var v = values[i];
    obj[ASSIGNMENT_HEADERS[i]] = (v instanceof Date) ? v.toISOString() : v;
  }
  return obj;
}

function findReviewRow_(applicationId, reviewerEmail) {
  var sheet = getSheet_(SHEET_REVIEWS);
  var last = sheet.getLastRow();
  if (last < 2) return null;
  var values = sheet.getRange(2, 1, last - 1, REVIEW_HEADERS.length).getValues();
  var emailLc = String(reviewerEmail).trim().toLowerCase();
  for (var i = 0; i < values.length; i++) {
    if (String(values[i][1]) === applicationId && String(values[i][2]).trim().toLowerCase() === emailLc) {
      return { row: i + 2, values: values[i] };
    }
  }
  return null;
}

function rowToReview_(values) {
  var obj = {};
  for (var i = 0; i < REVIEW_HEADERS.length; i++) {
    var v = values[i];
    obj[REVIEW_HEADERS[i]] = (v instanceof Date) ? v.toISOString() : v;
  }
  obj.sectionComments = safeParseJson_(obj.sectionComments, {});
  obj.rubricScores = safeParseJson_(obj.rubricScores, {});
  return obj;
}

function blankReview_(applicationId, reviewerEmail, semester) {
  return {
    reviewId: '',
    applicationId: applicationId,
    reviewerEmail: reviewerEmail,
    semester: semester,
    sectionComments: {},
    rubricScores: {},
    overallScore: 0,
    decision: '',
    signature: '',
    status: 'Draft',
    submittedAt: '',
    updatedAt: ''
  };
}

function upsertReview_(applicationId, reviewerEmail, semester, patch) {
  var sheet = getSheet_(SHEET_REVIEWS);
  var now = new Date().toISOString();
  var existingRow = findReviewRow_(applicationId, reviewerEmail);
  var base = existingRow ? rowToReview_(existingRow.values) : blankReview_(applicationId, reviewerEmail, semester);

  var merged = {
    reviewId: base.reviewId || ('REV-' + Utilities.getUuid().slice(0, 8).toUpperCase()),
    applicationId: applicationId,
    reviewerEmail: reviewerEmail,
    semester: semester,
    sectionComments: patch.sectionComments || base.sectionComments,
    rubricScores: patch.rubricScores || base.rubricScores,
    overallScore: (typeof patch.overallScore === 'number') ? patch.overallScore : base.overallScore,
    decision: (patch.decision !== undefined) ? patch.decision : base.decision,
    signature: (patch.signature !== undefined) ? patch.signature : base.signature,
    status: patch.status || base.status,
    submittedAt: patch.submittedAt || base.submittedAt,
    updatedAt: now
  };

  var row = [
    merged.reviewId, merged.applicationId, merged.reviewerEmail, merged.semester,
    JSON.stringify(merged.sectionComments), JSON.stringify(merged.rubricScores),
    merged.overallScore, merged.decision, merged.signature, merged.status,
    merged.submittedAt, merged.updatedAt
  ];

  if (existingRow) {
    sheet.getRange(existingRow.row, 1, 1, REVIEW_HEADERS.length).setValues([row]);
  } else {
    sheet.appendRow(row);
  }
}
function runThisOnce_registerReviewer() {
