}

/**
 * COORDINATOR SERVICE — Sprint 5
 * -----------------------------------------------------------------
 * The real "Assign Reviewers" / workload / semester-management UI
 * that 00_Core_Bootstrap.gs and 03_Reviewer_Service.gs originally
 * flagged as Sprint 5 scope. This file does NOT duplicate sheet-write
 * logic that already exists — it wraps adminAssignReviewer() /
 * adminRegisterReviewer() from 03_Reviewer_Service.gs and reads the
 * same Applications / Reviewers / Assignments sheets defined in
 * 00_Core_Bootstrap.gs.
 *
 * New sheet added: Coordinators (mirrors the Reviewers sheet pattern —
 * pre-provisioned, not self-signup). See the Bootstrap patch in
 * PROJECT.md §5 for the two lines added to 00_Core_Bootstrap.gs.
 * -----------------------------------------------------------------
 */

var SHEET_COORDINATORS = 'Coordinators';
var COORDINATOR_HEADERS = [
  'email',
  'fullName',
  'title',
  'active',      // TRUE/FALSE
  'updatedAt'
];

/**
 * Coordinator identity. Same gating pattern as identifyReviewer(): the
 * email must already exist in the Coordinators sheet with active=TRUE.
 * There is no self-signup for this role.
 * @param {string} emailFromClient
 * @returns {{email:string, displayName:string, title:string, semester:string}}
 */
function identifyCoordinator(emailFromClient) {
  var sessionEmail = '';
  try { sessionEmail = Session.getActiveUser().getEmail() || ''; } catch (err) { sessionEmail = ''; }

  var email = String(emailFromClient || sessionEmail || '').trim().toLowerCase();
  if (!email || email.indexOf('@') === -1) {
    throw new Error('A valid university email is required.');
  }

  var row = findCoordinatorRow_(email);
  if (!row) {
    throw new Error('This email is not registered as a coordinator. Contact the Ethics Committee.');
  }
  var coordinator = rowToCoordinator_(row.values);
  if (String(coordinator.active).toUpperCase() !== 'TRUE') {
    throw new Error('This coordinator account is inactive. Contact the Ethics Committee.');
  }

  return {
    email: coordinator.email,
    displayName: coordinator.fullName || guessDisplayName_(email),
    title: coordinator.title || '',
    semester: getCurrentSemester_()
  };
}

/**
 * Admin utility to add/reactivate a coordinator — same pattern as
 * adminRegisterReviewer(). Run once per coordinator from the Apps
 * Script editor (Faculty IT / the Ethics Committee sets this up).
 * @param {string} email
 * @param {string} fullName
 * @param {string} title
 */
function adminRegisterCoordinator(email, fullName, title) {
  email = String(email || '').trim().toLowerCase();
  if (!isValidUniversityEmail_(email)) throw new Error('Invalid email.');

  var sheet = getSheet_(SHEET_COORDINATORS);
  var now = new Date().toISOString();
  var row = [email, fullName || guessDisplayName_(email), title || '', 'TRUE', now];

  var existing = findCoordinatorRow_(email);
  if (existing) {
    sheet.getRange(existing.row, 1, 1, COORDINATOR_HEADERS.length).setValues([row]);
  } else {
    sheet.appendRow(row);
  }
  return rowToCoordinator_(row);
}

/**
 * Coordinator dashboard snapshot: how many submitted applications are
 * unassigned, in review, and completed this semester, plus the
 * current semester label.
 * @param {string} email
 * @returns {Object}
 */
function getCoordinatorDashboardData(email) {
  var identity = identifyCoordinator(email);
  var apps = listApplicationsForSemester_(identity.semester);

  var unassigned = 0, underReview = 0, completed = 0, draft = 0;
  apps.forEach(function (a) {
    if (a.status === 'Draft') draft++;
    else if (a.status === 'Submitted') unassigned++;
    else if (a.status === 'Under Review') underReview++;
    else completed++; // Approved / Rejected / Revisions
  });

  return {
    coordinatorName: identity.displayName,
    semester: identity.semester,
    totalApplications: apps.length,
    unassignedCount: unassigned,
    underReviewCount: underReview,
    completedCount: completed,
    draftCount: draft
  };
}

/**
 * Every application in the current semester, joined with its
 * assignment rows (which reviewer(s), due date, status) so the
 * coordinator can see and manage everything from one table.
 * @param {string} email
 * @returns {Object[]}
 */
function getApplicationsForCoordinator(email) {
  var identity = identifyCoordinator(email);
  var apps = listApplicationsForSemester_(identity.semester);
  var allAssignments = listAllAssignments_();

  return apps.map(function (app) {
    var assignmentsForApp = allAssignments.filter(function (a) {
      return a.applicationId === app.applicationId;
    });
    var form = safeParseJson_(app.formData, {});
    return {
      applicationId: app.applicationId,
      projectTitle: form.projectTitle || '(untitled)',
      studentName: form.fullName || app.studentEmail,
      studentEmail: app.studentEmail,
      status: app.status,
      submittedAt: app.submittedAt || '',
      assignments: assignmentsForApp.map(function (a) {
        return {
          assignmentId: a.assignmentId,
          reviewerEmail: a.reviewerEmail,
          dueDate: a.dueDate,
          status: a.status
        };
      })
    };
  }).sort(function (a, b) {
    // Newest submissions first; drafts (no submittedAt) sink to the bottom.
    if (!a.submittedAt) return 1;
    if (!b.submittedAt) return -1;
    return b.submittedAt.localeCompare(a.submittedAt);
  });
}

/**
 * Every active reviewer, with their current workload counts for the
 * current semester — used for the workload-balancing view and as the
 * basis for the recommendation engine below.
 * @param {string} email
 * @returns {Object[]}
 */
function getReviewerWorkloads(email) {
  var identity = identifyCoordinator(email);
  var reviewers = listActiveReviewers_();
  var allAssignments = listAllAssignments_().filter(function (a) {
    return a.semester === identity.semester;
  });

  return reviewers.map(function (r) {
    var mine = allAssignments.filter(function (a) {
      return String(a.reviewerEmail).toLowerCase() === r.email.toLowerCase();
    });
    var pending = mine.filter(function (a) { return a.status !== 'Completed'; }).length;
    var completed = mine.filter(function (a) { return a.status === 'Completed'; }).length;
    return {
      email: r.email,
      displayName: r.fullName || guessDisplayName_(r.email),
      title: r.title || '',
      specialization: r.specialization || '',
      totalAssigned: mine.length,
      pendingCount: pending,
      completedCount: completed
    };
  }).sort(function (a, b) { return a.pendingCount - b.pendingCount; }); // lightest load first
}

/**
 * Simple rule-based recommendation: the active reviewer with the
 * fewest pending (non-completed) assignments this semester, optionally
 * preferring a specialization keyword match against the application's
 * ethics-screening flags. This is intentionally simple (no ML) — a
 * transparent, explainable suggestion the coordinator can override.
 * @param {string} email
 * @param {string} applicationId
 * @returns {Object[]} reviewers ranked best-first, each with a `reason`
 */
function recommendReviewersForApplication(email, applicationId) {
  var identity = identifyCoordinator(email);
  var appRow = findApplicationRowById_(applicationId);
  if (!appRow) throw new Error('Application not found.');
  var app = rowToApp_(appRow.values);
  var form = safeParseJson_(app.formData, {});
  var flags = (form.ethicsFlags || []).map(function (f) { return String(f).toLowerCase(); });

  var workloads = getReviewerWorkloads(email); // already sorted lightest-first

  return workloads.map(function (r) {
    var spec = String(r.specialization || '').toLowerCase();
    var matches = flags.filter(function (f) { return spec.indexOf(f) !== -1; });
    return {
      email: r.email,
      displayName: r.displayName,
      pendingCount: r.pendingCount,
      specializationMatch: matches.length > 0,
      reason: matches.length > 0
        ? ('Specialization overlaps with: ' + matches.join(', '))
        : ('Lightest current workload (' + r.pendingCount + ' pending)')
    };
  }).sort(function (a, b) {
    // Specialization match first, then lightest workload.
    if (a.specializationMatch !== b.specializationMatch) return a.specializationMatch ? -1 : 1;
    return a.pendingCount - b.pendingCount;
  });
}

/**
 * Assign a reviewer to an application. Thin wrapper around the
 * existing adminAssignReviewer() in 03_Reviewer_Service.gs — no
 * sheet-write logic is duplicated here.
 * @param {string} email - coordinator email (for auth check)
 * @param {string} applicationId
 * @param {string} reviewerEmail
 * @param {string} dueDateIso
 */
function assignReviewer(email, applicationId, reviewerEmail, dueDateIso) {
  identifyCoordinator(email); // throws if not a valid coordinator
  adminAssignReviewer(applicationId, reviewerEmail, dueDateIso || '');
  return getApplicationsForCoordinator(email);
}

/**
 * Update the due date on an existing assignment.
 * @param {string} email
 * @param {string} assignmentId
 * @param {string} dueDateIso
 */
function updateAssignmentDueDate(email, assignmentId, dueDateIso) {
  identifyCoordinator(email);
  var sheet = getSheet_(SHEET_ASSIGNMENTS);
  var last = sheet.getLastRow();
  if (last < 2) return;
  var values = sheet.getRange(2, 1, last - 1, ASSIGNMENT_HEADERS.length).getValues();
  for (var i = 0; i < values.length; i++) {
    if (String(values[i][0]) === assignmentId) {
      sheet.getRange(i + 2, ASSIGNMENT_HEADERS.indexOf('dueDate') + 1).setValue(dueDateIso || '');
      return;
    }
