/**
 * Remove/unassign a reviewer from an application (e.g. reassigning).
 * Deletes the Assignments row; does not touch any Review draft that
 * reviewer may already have started (left as an audit trail).
 * @param {string} email
 * @param {string} assignmentId
 */
function removeAssignment(email, assignmentId) {
  identifyCoordinator(email);
  var sheet = getSheet_(SHEET_ASSIGNMENTS);
  var last = sheet.getLastRow();
  if (last < 2) return;
  var values = sheet.getRange(2, 1, last - 1, ASSIGNMENT_HEADERS.length).getValues();
  for (var i = 0; i < values.length; i++) {
    if (String(values[i][0]) === assignmentId) {
      sheet.deleteRow(i + 2);
      return;
    }
  }
}

/**
 * Read/update the active semester (Config sheet, 'CurrentSemester'
 * row) — reuses getCurrentSemester_() from 00_Core_Bootstrap.gs and
 * writes back through the same sheet.
 * @param {string} email
 * @param {string} newSemester - omit to just read the current value
 * @returns {string}
 */
function manageSemester(email, newSemester) {
  identifyCoordinator(email);
  var sheet = getSheet_(SHEET_CONFIG);
  if (newSemester) {
    var data = sheet.getDataRange().getValues();
    var found = false;
    for (var i = 1; i < data.length; i++) {
      if (String(data[i][0]) === 'CurrentSemester') {
        sheet.getRange(i + 1, 2).setValue(newSemester);
        found = true;
        break;
      }
    }
    if (!found) sheet.appendRow(['CurrentSemester', newSemester]);
  }
  return getCurrentSemester_();
}

/**
 * Every distinct semester value seen across all applications, for the
 * semester-switcher dropdown.
 * @returns {string[]}
 */
function listKnownSemesters_() {
  var sheet = getSheet_(SHEET_APPLICATIONS);
  var last = sheet.getLastRow();
  if (last < 2) return [getCurrentSemester_()];
  var col = APP_HEADERS.indexOf('semester') + 1;
  var values = sheet.getRange(2, col, last - 1, 1).getValues();
  var set = {};
  values.forEach(function (row) { if (row[0]) set[String(row[0])] = true; });
  set[getCurrentSemester_()] = true;
  return Object.keys(set).sort();
}

/**
 * CSV export of the current semester's applications + assignment
 * summary — a lightweight stand-in for the full Excel/PDF export
 * that's Sprint 7 scope. Returns a CSV string the client turns into
 * a downloadable file (see CoordinatorDashboardScript.html).
 * @param {string} email
 * @returns {string}
 */
function exportApplicationsCsv(email) {
  var rows = getApplicationsForCoordinator(email);
  var lines = ['Application ID,Project Title,Student,Status,Submitted At,Assigned Reviewer(s),Due Date(s)'];
  rows.forEach(function (r) {
    var reviewers = r.assignments.map(function (a) { return a.reviewerEmail; }).join('; ');
    var dueDates = r.assignments.map(function (a) { return a.dueDate; }).join('; ');
    var csvEscape = function (v) { return '"' + String(v || '').replace(/"/g, '""') + '"'; };
    lines.push([
      csvEscape(r.applicationId), csvEscape(r.projectTitle), csvEscape(r.studentName),
      csvEscape(r.status), csvEscape(r.submittedAt), csvEscape(reviewers), csvEscape(dueDates)
    ].join(','));
  });
  return lines.join('\n');
}

/* ------------------------------------------------------------------
