function findCoordinatorRow_(email) {
  var sheet = getSheet_(SHEET_COORDINATORS);
  var last = sheet.getLastRow();
  if (last < 2) return null;
  var values = sheet.getRange(2, 1, last - 1, COORDINATOR_HEADERS.length).getValues();
  var emailLc = String(email).trim().toLowerCase();
  for (var i = 0; i < values.length; i++) {
    if (String(values[i][0]).trim().toLowerCase() === emailLc) return { row: i + 2, values: values[i] };
  }
  return null;
}

function rowToCoordinator_(values) {
  var obj = {};
  for (var i = 0; i < COORDINATOR_HEADERS.length; i++) {
    var v = values[i];
    obj[COORDINATOR_HEADERS[i]] = (v instanceof Date) ? v.toISOString() : v;
  }
  return obj;
}

function listApplicationsForSemester_(semester) {
