/**
 * AUTOMATION — Archive completed applications (Sprint 6)
 * -----------------------------------------------------------------
 * Moves applications whose status is Approved or Rejected out of the
 * live Applications sheet into a new Archive sheet, so the coordinator's
 * working tables stay focused on active work — while every archived
 * row remains fully intact and retrievable, never deleted.
 * -----------------------------------------------------------------
 */

var SHEET_ARCHIVE = 'Archive';
var ARCHIVE_HEADERS = APP_HEADERS.concat(['archivedAt']);
var ARCHIVABLE_STATUSES_ = ['Approved', 'Rejected'];

function ensureArchiveSheet_(ss) {
  ensureSheetWithHeaders_(ss, SHEET_ARCHIVE, ARCHIVE_HEADERS);
}

/**
 * Coordinator-facing action: archive every Approved/Rejected
 * application currently in the live Applications sheet.
 * @param {string} email - coordinator email (auth check)
 * @returns {{archivedCount:number}}
 */
function archiveCompletedApplications(email) {
  identifyCoordinator(email); // throws if not a valid, active coordinator
  return archiveCompletedApplications_();
}

/**
 * Same operation, callable with no auth check — used by the optional
 * daily archive trigger (createDailyArchiveTrigger()) where there's no
 * signed-in coordinator to check against.
 * @returns {{archivedCount:number}}
 */
function archiveCompletedApplications_() {
  var ss = ensureSpreadsheet_();
  ensureArchiveSheet_(ss);

  var appsSheet = ss.getSheetByName(SHEET_APPLICATIONS);
  var archiveSheet = ss.getSheetByName(SHEET_ARCHIVE);
  var last = appsSheet.getLastRow();
  if (last < 2) return { archivedCount: 0 };

  var values = appsSheet.getRange(2, 1, last - 1, APP_HEADERS.length).getValues();
  var now = new Date().toISOString();
  var archivedCount = 0;

  for (var i = values.length - 1; i >= 0; i--) {
    var app = rowToApp_(values[i]);
    if (ARCHIVABLE_STATUSES_.indexOf(app.status) === -1) continue;

    archiveSheet.appendRow(values[i].concat([now]));
    appsSheet.deleteRow(i + 2);
    archivedCount++;
  }

  return { archivedCount: archivedCount };
}

/**
 * Coordinator-facing read: list every archived application (newest
 * archivedAt first), joined with its project title for display.
 * @param {string} email
 * @returns {Object[]}
 */
function getArchivedApplications(email) {
  identifyCoordinator(email);
  var ss = ensureSpreadsheet_();
  ensureArchiveSheet_(ss);
  var sheet = ss.getSheetByName(SHEET_ARCHIVE);
  var last = sheet.getLastRow();
  if (last < 2) return [];

  var values = sheet.getRange(2, 1, last - 1, ARCHIVE_HEADERS.length).getValues();
  var out = values.map(function (row) {
    var app = {};
    for (var i = 0; i < APP_HEADERS.length; i++) app[APP_HEADERS[i]] = row[i];
    var archivedAt = row[APP_HEADERS.length];
    var form = safeParseJson_(app.formData, {});
    return {
      applicationId: app.applicationId,
      projectTitle: form.projectTitle || '(untitled)',
      studentEmail: app.studentEmail,
      semester: app.semester,
      status: app.status,
      submittedAt: app.submittedAt || '',
      archivedAt: archivedAt || ''
    };
  });

  out.sort(function (a, b) { return String(b.archivedAt).localeCompare(String(a.archivedAt)); });
  return out;
}

/**
 * Optional one-time setup: run from the Apps Script editor to archive
 * completed applications automatically once a day at 3am, instead of
 * relying on a coordinator clicking the "Archive" button. Safe to
 * re-run — clears any existing trigger for this function first.
 */
function createDailyArchiveTrigger() {
  removeArchiveTriggers_();
  ScriptApp.newTrigger('archiveCompletedApplications_')
    .timeBased()
    .atHour(3)
    .everyDays(1)
    .create();
}

function removeArchiveTriggers_() {
  ScriptApp.getProjectTriggers().forEach(function (t) {
    if (t.getHandlerFunction() === 'archiveCompletedApplications_') {
      ScriptApp.deleteTrigger(t);
    }
  });
}

/**
 * AUTOMATION — Status-change email notifications (Sprint 6)
 * -----------------------------------------------------------------
 * Sends a direct email to the student the moment their application's
 * status changes to one of: Submitted, Under Review, Revision
 * Requested, Approved, Rejected.
 *
 * Called at the point of the action (not on a timer):
 *   - submitApplication()          → 01_Application_Service.gs
 *   - submitReview()               → 03_Reviewer_Service.gs (decision saved)
 *   - adminAssignReviewer()        → 03_Reviewer_Service.gs (Submitted -> Under Review)
 *
 * Deadline reminders (a different kind of email, sent on a schedule
 * rather than on an action) live in 06_Automation_Reminders.gs.
 *
 * Design note: notifyStudentStatusChange_() NEVER throws. A student's
 * submission or a reviewer's decision must still succeed and be saved
 * even if Gmail/MailApp is down, over quota, or the address bounces —
 * so every failure here is caught and logged, not propagated.
 * -----------------------------------------------------------------
 */

/**
 * @param {string} applicationId
 * @param {string} newStatus - one of the STATUS_EMAIL_CONTENT_ keys below
 */
function notifyStudentStatusChange_(applicationId, newStatus) {
  try {
    var appRow = findApplicationRowById_(applicationId);
    if (!appRow) return; // nothing to notify about

    var app = rowToApp_(appRow.values);
    var form = safeParseJson_(app.formData, {});
    var studentEmail = String(app.studentEmail || '').trim();
    if (!studentEmail || studentEmail.indexOf('@') === -1) return;

    var content = buildStatusEmailContent_(newStatus, {
      studentName: form.fullName || guessDisplayName_(studentEmail),
      projectTitle: form.projectTitle || '(untitled project)',
      applicationId: applicationId
    });
    if (!content) return; // unrecognized/no-op status — nothing to send

    MailApp.sendEmail({
      to: studentEmail,
      subject: content.subject,
      body: content.body
    });
  } catch (err) {
    // Swallow — see file header. Leave a trace in Stackdriver for later.
    console.error('notifyStudentStatusChange_ failed for ' + applicationId + ': ' + err);
  }
}

/**
 * Builds the subject/body pair for a given status. Returns null for any
 * status that isn't one of the five Sprint 6 notification triggers
 * (e.g. 'Draft' — nothing is emailed for ordinary autosaves).
 * @param {string} status
 * @param {{studentName:string, projectTitle:string, applicationId:string}} ctx
 * @returns {{subject:string, body:string}|null}
 */
function buildStatusEmailContent_(status, ctx) {
  var portalUrl = getPortalUrl_();
  var linkLine = portalUrl ? ('\n\nView your application: ' + portalUrl) : '';
  var signOff = '\n\n— BioEthics Portal, Faculty of Biotechnology, MSA University';
  var greeting = 'Dear ' + (ctx.studentName || 'Student') + ',\n\n';

  var byStatus = {
    'Submitted': {
      subject: 'UREC: Application Submitted — ' + ctx.projectTitle,
      body: greeting +
        'Your ethics application "' + ctx.projectTitle + '" (Ref: ' + ctx.applicationId + ') ' +
        'has been submitted successfully and is awaiting assignment to the University ' +
        'Research Ethics Committee (UREC).' + linkLine + signOff
    },
    'Under Review': {
      subject: 'UREC: Application Under Review — ' + ctx.projectTitle,
      body: greeting +
        'Your ethics application "' + ctx.projectTitle + '" (Ref: ' + ctx.applicationId + ') ' +
        'has been assigned to a reviewer and is now under review.' + linkLine + signOff
    },
    'Revision Requested': {
      subject: 'UREC: Revisions Requested — ' + ctx.projectTitle,
      body: greeting +
        'The committee has reviewed your ethics application "' + ctx.projectTitle + '" ' +
        '(Ref: ' + ctx.applicationId + ') and has requested revisions before it can be ' +
        'approved. Please sign in to the portal to see the reviewer\'s comments.' + linkLine + signOff
    },
    'Approved': {
      subject: 'UREC: Application Approved — ' + ctx.projectTitle,
      body: greeting +
        'Congratulations — your ethics application "' + ctx.projectTitle + '" ' +
        '(Ref: ' + ctx.applicationId + ') has been APPROVED by the committee.' + linkLine + signOff
    },
    'Rejected': {
      subject: 'UREC: Application Rejected — ' + ctx.projectTitle,
      body: greeting +
        'The committee has reviewed your ethics application "' + ctx.projectTitle + '" ' +
        '(Ref: ' + ctx.applicationId + ') and has not ' +
        'approved it at this time. Please sign in to the portal for the reviewer\'s comments.' + linkLine + signOff
    }
  };

  return byStatus[status] || null;
}

/**
 * Best-effort web app URL for links inside notification emails. Returns
 * '' (rather than throwing) when called somewhere without a deployed
 * web app context, e.g. certain trigger executions.
 * @returns {string}
 */
function getPortalUrl_() {
  try {
    return ScriptApp.getService().getUrl() || '';
  } catch (err) {
    return '';
  }
}
/**
 * Sprint 6 — Reviewer assignment digest email.
 * Called whenever a reviewer gets a new assignment (adminAssignReviewer).
 * Sends ONE email listing every currently-pending (not yet Completed)
 * assignment for that reviewer — not one email per assignment — so
 * assigning someone 10 applications in a row sends 10 refreshed digest
 * emails, each showing the complete up-to-date list, rather than
 * flooding their inbox with 10 separate notifications.
 * @param {string} reviewerEmail
 */
function notifyReviewerAssigned_(reviewerEmail) {
  try {
    var email = String(reviewerEmail || '').trim().toLowerCase();
    if (!email || email.indexOf('@') === -1) return;

    var pending = listAssignmentsForReviewer_(email).filter(function (a) {
      return a.status !== 'Completed';
    });
    if (!pending.length) return;

    var reviewerRow = findReviewerRow_(email);
    var reviewerName = reviewerRow ? (rowToReviewer_(reviewerRow.values).fullName || guessDisplayName_(email)) : guessDisplayName_(email);

    var lines = pending.map(function (a) {
      var appRow = findApplicationRowById_(a.applicationId);
      var form = appRow ? safeParseJson_(rowToApp_(appRow.values).formData, {}) : {};
      var due = a.dueDate ? (' — due ' + formatDisplayDate_(a.dueDate)) : '';
      return '  • ' + (form.projectTitle || '(untitled project)') + ' (Ref: ' + a.applicationId + ')' + due;
    });

    var portalUrl = getPortalUrl_();
    var body = 'Dear ' + reviewerName + ',\n\n' +
      'You currently have ' + pending.length + ' ethics application(s) assigned to you for review:\n\n' +
      lines.join('\n') +
      (portalUrl ? ('\n\nOpen the Reviewer Portal: ' + portalUrl) : '') +
      '\n\n— BioEthics Portal, Faculty of Biotechnology, MSA University';

    MailApp.sendEmail({
      to: email,
      subject: 'UREC: You have ' + pending.length + ' application(s) assigned for review',
      body: body
    });
  } catch (err) {
    console.error('notifyReviewerAssigned_ failed for ' + reviewerEmail + ': ' + err);
  }
}
/**
 * Sprint 7 — Batched reviewer-assignment digest. Triggered explicitly
 * by a coordinator via a dashboard button — NOT automatically per
 * assignment. Finds every assignment row still marked notified=FALSE,
 * groups by reviewer, sends ONE email per reviewer listing everything
 * new since their last notification, then marks those rows notified.
 * @param {string} coordinatorEmail
 * @returns {{notifiedReviewers:number, assignmentsIncluded:number}}
 */
function notifyPendingReviewerAssignments(coordinatorEmail) {
  identifyCoordinator(coordinatorEmail); // throws if not a valid coordinator

  var sheet = getSheet_(SHEET_ASSIGNMENTS);
  var last = sheet.getLastRow();
  if (last < 2) return { notifiedReviewers: 0, assignmentsIncluded: 0 };

  var values = sheet.getRange(2, 1, last - 1, ASSIGNMENT_HEADERS.length).getValues();
  var notifiedCol = ASSIGNMENT_HEADERS.indexOf('notified');
  var byReviewer = {};

  values.forEach(function (row, idx) {
    var isNotified = String(row[notifiedCol]).toUpperCase() === 'TRUE';
    if (isNotified) return;
    var email = String(row[2] || '').trim().toLowerCase();
    if (!email) return;
    if (!byReviewer[email]) byReviewer[email] = [];
    byReviewer[email].push({ rowIndex: idx, applicationId: row[1], dueDate: row[5] });
  });

  var reviewerEmails = Object.keys(byReviewer);
  var assignmentsIncluded = 0;
  var rowsToMarkNotified = [];

  reviewerEmails.forEach(function (email) {
    var items = byReviewer[email];
    try {
      var reviewerRow = findReviewerRow_(email);
      var reviewerName = reviewerRow ? (rowToReviewer_(reviewerRow.values).fullName || guessDisplayName_(email)) : guessDisplayName_(email);

      var lines = items.map(function (it) {
        var appRow = findApplicationRowById_(it.applicationId);
        var form = appRow ? safeParseJson_(rowToApp_(appRow.values).formData, {}) : {};
        var due = it.dueDate ? (' — due ' + formatDisplayDate_(it.dueDate)) : '';
        return '  • ' + (form.projectTitle || '(untitled project)') + ' (Ref: ' + it.applicationId + ')' + due;
      });

      var portalUrl = getPortalUrl_();
      var body = 'Dear ' + reviewerName + ',\n\n' +
        'You have been assigned ' + items.length + ' new ethics application(s) to review:\n\n' +
        lines.join('\n') +
        (portalUrl ? ('\n\nOpen the Reviewer Portal: ' + portalUrl) : '') +
        '\n\n— BioEthics Portal, Faculty of Biotechnology, MSA University';

      MailApp.sendEmail({
        to: email,
        subject: 'UREC: ' + items.length + ' new application(s) assigned for review',
        body: body
      });

      items.forEach(function (it) { rowsToMarkNotified.push(it.rowIndex); });
      assignmentsIncluded += items.length;
    } catch (err) {
      console.error('notifyPendingReviewerAssignments failed for ' + email + ': ' + err);
    }
  });

  rowsToMarkNotified.forEach(function (idx) {
    sheet.getRange(idx + 2, notifiedCol + 1).setValue('TRUE');
  });

  return { notifiedReviewers: reviewerEmails.length, assignmentsIncluded: assignmentsIncluded };
}

/**
 * AUTOMATION — Real document export for a submitted application (Sprint 6)
 * -----------------------------------------------------------------
 * Replaces the Wizard's browser "Print / Save as PDF" (window.print())
 * with actual server-side file generation, saved to Drive and returned
 * as a download link — for both PDF and, where practical, Word (.docx).
 *
 * Storage reuses the SAME per-application Drive folder that
 * 01_Application_FilesService.gs already creates for annex uploads
 * (getOrCreateApplicationUploadFolder_) — no new folder scheme is
 * introduced. Exported files are named so re-generating an export
 * replaces the previous one instead of piling up duplicates.
 *
 * PDF: HtmlService.createHtmlOutput(html).getAs(MimeType.PDF) — this is
 * Apps Script's built-in HTML-to-PDF conversion, no external service.
 *
 * Word (.docx): built as a real Google Doc with DocumentApp, then
 * exported to real .docx bytes via the Drive API export endpoint
 * (UrlFetchApp + ScriptApp.getOAuthToken() — no external library needed).
 * -----------------------------------------------------------------
 */

var DOCX_EXPORT_MIME_ = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';

/**
 * Generates (or regenerates) a PDF of a submitted application and
 * returns a Drive download link.
 * @param {string} email - caller's email (student owner, assigned reviewer, or coordinator)
 * @param {string} applicationId
 * @returns {{fileName:string, url:string, fileId:string}}
 */
function generateApplicationPdf(email, applicationId) {
  var appRow = findApplicationRowById_(applicationId);
  if (!appRow) throw new Error('Application not found.');
  var app = rowToApp_(appRow.values);
  assertCanAccessApplicationForExport_(email, applicationId, app);
  if (app.status === 'Draft') {
    throw new Error('This application has not been submitted yet — nothing to export.');
  }

  var form = safeParseJson_(app.formData, {});
  var requiredAnnexes = safeParseJson_(app.requiredAnnexes, []);
  var html = buildApplicationExportHtml_(app, form, requiredAnnexes);

  var pdfBlob = HtmlService.createHtmlOutput(html)
    .getAs('application/pdf')
    .setName(applicationId + '_Ethics_Application.pdf');

  var folder = getOrCreateApplicationUploadFolder_(applicationId);
  replaceExistingFile_(folder, pdfBlob.getName());
  var file = folder.createFile(pdfBlob);

  return { fileName: file.getName(), url: file.getUrl(), fileId: file.getId() };
}

/**
 * Generates (or regenerates) a Word (.docx) copy of a submitted
 * application and returns a Drive download link.
 * @param {string} email
 * @param {string} applicationId
 * @returns {{fileName:string, url:string, fileId:string}}
 */
function generateApplicationDocx(email, applicationId) {
  var appRow = findApplicationRowById_(applicationId);
  if (!appRow) throw new Error('Application not found.');
  var app = rowToApp_(appRow.values);
  assertCanAccessApplicationForExport_(email, applicationId, app);
  if (app.status === 'Draft') {
    throw new Error('This application has not been submitted yet — nothing to export.');
  }

  var form = safeParseJson_(app.formData, {});
  var requiredAnnexes = safeParseJson_(app.requiredAnnexes, []);
  var fileName = applicationId + '_Ethics_Application.docx';

  var tempDoc = DocumentApp.create('__tmp_export_' + applicationId);
  populateExportDoc_(tempDoc, app, form, requiredAnnexes);
  tempDoc.saveAndClose();

  try {
    var url = 'https://www.googleapis.com/drive/v3/files/' + tempDoc.getId() +
      '/export?mimeType=' + encodeURIComponent(DOCX_EXPORT_MIME_);
    var resp = UrlFetchApp.fetch(url, {
      headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken() },
      muteHttpExceptions: true
    });
    if (resp.getResponseCode() !== 200) {
      throw new Error('Drive export failed (HTTP ' + resp.getResponseCode() + ').');
    }
    var docxBlob = resp.getBlob().setName(fileName);

    var folder = getOrCreateApplicationUploadFolder_(applicationId);
    replaceExistingFile_(folder, fileName);
    var file = folder.createFile(docxBlob);

    return { fileName: file.getName(), url: file.getUrl(), fileId: file.getId() };
  } finally {
    try { DriveApp.getFileById(tempDoc.getId()).setTrashed(true); } catch (e) { /* ignore */ }
  }
}

/**
 * Access check shared by both export functions: the student who owns
 * the application, an assigned reviewer, or any active coordinator may
 * export it. Throws if none of those match.
 * @param {string} email
 * @param {string} applicationId
 * @param {Object} app - rowToApp_() result
 */
function assertCanAccessApplicationForExport_(email, applicationId, app) {
  var normalized = String(email || '').trim().toLowerCase();
  if (!normalized) throw new Error('A valid university email is required.');

  if (String(app.studentEmail || '').toLowerCase() === normalized) return; // owner
  var coordinatorRow = findCoordinatorRow_(normalized);
  if (coordinatorRow && String(rowToCoordinator_(coordinatorRow.values).active).toUpperCase() === 'TRUE') return;
  if (findAssignment_(applicationId, normalized)) return; // assigned reviewer

  throw new Error('You do not have access to this application.');
}

/**
 * If a file with this exact name already exists in the folder, trash
 * it first — keeps re-generating an export a clean replace, not a
 * pile of "final_v2_v3" duplicates.
 * @param {GoogleAppsScript.Drive.Folder} folder
 * @param {string} fileName
 */
function replaceExistingFile_(folder, fileName) {
  var existing = folder.getFilesByName(fileName);
  while (existing.hasNext()) {
    existing.next().setTrashed(true);
  }
}

/**
 * Plain-HTML rendering of the application, shared content source for
 * the PDF export.
 */
function buildApplicationExportHtml_(app, form, requiredAnnexes) {
  var esc = function (v) { return String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;'); };
  var row = function (label, value) {
    return '<tr><td style="font-weight:bold;padding:4px 8px;border:1px solid #ccc;width:35%;">' + esc(label) +
      '</td><td style="padding:4px 8px;border:1px solid #ccc;">' + esc(value) + '</td></tr>';
  };

  return '<html><body style="font-family:Georgia,serif;color:#1c2b39;font-size:12px;">' +
    '<h1 style="font-size:18px;border-bottom:2px solid #1c2b39;padding-bottom:6px;">' +
    'BioEthics Portal — Ethics Application</h1>' +
    '<p style="color:#555;">Faculty of Biotechnology, MSA University</p>' +
    '<table style="border-collapse:collapse;width:100%;margin-top:12px;">' +
    row('Application Ref', app.applicationId) +
    row('Status', app.status) +
    row('Semester', app.semester) +
    row('Submitted At', formatDisplayDate_(app.submittedAt)) +
    row('Student Name', form.fullName) +
    row('Student ID', form.studentId) +
    row('University Email', form.universityEmail) +
    row('Programme', form.programme) +
    row('Internal Supervisor', form.internalSupervisor) +
    row('External Supervisor', form.externalSupervisor) +
    row('Project Title', form.projectTitle) +
    row('Research Category', form.researchCategory) +
    row('Start Date', form.startDate) +
    row('End Date', form.endDate) +
    '</table>' +
    '<h2 style="font-size:14px;margin-top:16px;">Purpose of Research</h2>' +
    '<p>' + esc(form.purposeOfResearch) + '</p>' +
    '<h2 style="font-size:14px;">Background</h2>' +
    '<p>' + esc(form.background) + '</p>' +
    '<h2 style="font-size:14px;">Research Aim</h2>' +
    '<p>' + esc(form.researchAim) + '</p>' +
    '<h2 style="font-size:14px;">Methodology</h2>' +
    '<p>' + esc(form.methodology) + '</p>' +
    '<h2 style="font-size:14px;">Ethics Screening Flags</h2>' +
    '<p>' + esc((form.ethicsFlags || []).join(', ') || 'None') + '</p>' +
    '<h2 style="font-size:14px;">Required Annexes</h2>' +
    '<p>' + esc((requiredAnnexes || []).join(', ') || 'None') + '</p>' +
    '</body></html>';
}

/**
 * Same content as buildApplicationExportHtml_(), but written directly
 * with DocumentApp calls so the result is a genuine Google Doc.
 */
function populateExportDoc_(doc, app, form, requiredAnnexes) {
  var body = doc.getBody();
  body.appendParagraph('BioEthics Portal — Ethics Application').setHeading(DocumentApp.ParagraphHeading.HEADING1);
  body.appendParagraph('Faculty of Biotechnology, MSA University');

  var table = [
    ['Application Ref', app.applicationId],
    ['Status', app.status],
    ['Semester', app.semester],
    ['Submitted At', formatDisplayDate_(app.submittedAt)],
    ['Student Name', form.fullName || ''],
    ['Student ID', form.studentId || ''],
    ['University Email', form.universityEmail || ''],
    ['Programme', form.programme || ''],
    ['Internal Supervisor', form.internalSupervisor || ''],
    ['External Supervisor', form.externalSupervisor || ''],
    ['Project Title', form.projectTitle || ''],
    ['Research Category', form.researchCategory || ''],
    ['Start Date', form.startDate || ''],
    ['End Date', form.endDate || '']
  ];
  body.appendTable(table);

  var sections = [
    ['Purpose of Research', form.purposeOfResearch],
    ['Background', form.background],
    ['Research Aim', form.researchAim],
    ['Methodology', form.methodology],
    ['Ethics Screening Flags', (form.ethicsFlags || []).join(', ') || 'None'],
    ['Required Annexes', (requiredAnnexes || []).join(', ') || 'None']
  ];
  sections.forEach(function (pair) {
    body.appendParagraph(pair[0]).setHeading(DocumentApp.ParagraphHeading.HEADING2);
    body.appendParagraph(String(pair[1] || ''));
  });
}

/**
 * AUTOMATION — Deadline reminder emails (Sprint 6)
 * -----------------------------------------------------------------
 * Run once a day by a time-driven trigger (see createDailyRemindersTrigger()
 * below). Sends two kinds of reminder:
 *
 *   1. To reviewers — an assignment's due date is approaching or overdue.
 *   2. To coordinators — one or more applications have been sitting in
 *      'Submitted' (i.e. awaiting reviewer assignment) too long.
 *
 * This file only reads sheets via the existing helpers already defined
 * in 00_Core_Bootstrap.gs / 03_Reviewer_Service.gs / 04_Coordinator_Service.gs
 * (getSheet_, rowToAssignment_, rowToApp_, rowToCoordinator_, etc.) — no
 * sheet-read/write logic is duplicated here.
 * -----------------------------------------------------------------
 */

// A reviewer gets a reminder once their assignment is within this many
// days of its due date (or already overdue).
var REMINDER_DUE_SOON_DAYS = 2;

// A coordinator gets a reminder about any application that has sat in
// 'Submitted' (unassigned) for at least this many days.
var REMINDER_STALE_UNASSIGNED_DAYS = 5;

/**
 * Entry point for the daily trigger. Safe to run manually too (e.g. from
 * the Apps Script editor) to test — it only sends mail, no writes.
 */
function checkDeadlinesAndSendReminders() {
  sendReviewerDeadlineReminders_();
  sendCoordinatorUnassignedReminders_();
}

/**
 * One email per reviewer (not per assignment) listing every
 * not-yet-completed assignment that's due soon or overdue.
 */
function sendReviewerDeadlineReminders_() {
  var assignments = listAllAssignments_().filter(function (a) {
    return a.status !== 'Completed' && a.dueDate;
  });
  if (!assignments.length) return;

  var now = new Date();
  var byReviewer = {}; // email -> [ {applicationId, projectTitle, dueDate, daysUntilDue, overdue} ]

  assignments.forEach(function (a) {
    var due = new Date(a.dueDate);
    if (isNaN(due.getTime())) return;
    var daysUntilDue = Math.floor((due - now) / (24 * 60 * 60 * 1000));
    if (daysUntilDue > REMINDER_DUE_SOON_DAYS) return; // not due soon yet

    var appRow = findApplicationRowById_(a.applicationId);
    var form = appRow ? safeParseJson_(rowToApp_(appRow.values).formData, {}) : {};
    var key = String(a.reviewerEmail || '').toLowerCase();
    if (!key || key.indexOf('@') === -1) return;

    if (!byReviewer[key]) byReviewer[key] = [];
    byReviewer[key].push({
      applicationId: a.applicationId,
      projectTitle: form.projectTitle || '(untitled project)',
      dueDate: a.dueDate,
      daysUntilDue: daysUntilDue,
      overdue: daysUntilDue < 0
    });
  });

  Object.keys(byReviewer).forEach(function (email) {
    try {
      var items = byReviewer[email];
      var reviewerRow = findReviewerRow_(email);
      var reviewerName = reviewerRow ? (rowToReviewer_(reviewerRow.values).fullName || guessDisplayName_(email)) : guessDisplayName_(email);

      var lines = items.map(function (it) {
        var when = it.overdue
          ? (Math.abs(it.daysUntilDue) + ' day(s) OVERDUE')
          : (it.daysUntilDue === 0 ? 'due TODAY' : ('due in ' + it.daysUntilDue + ' day(s)'));
        return '  • ' + it.projectTitle + ' (Ref: ' + it.applicationId + ') — ' + when + ' (' + formatDisplayDate_(it.dueDate) + ')';
      });

      var portalUrl = getPortalUrl_();
      var body = 'Dear ' + reviewerName + ',\n\n' +
        'The following ethics review assignment(s) need your attention:\n\n' +
        lines.join('\n') +
        (portalUrl ? ('\n\nOpen the Reviewer Portal: ' + portalUrl) : '') +
        '\n\n— BioEthics Portal, Faculty of Biotechnology, MSA University';

      MailApp.sendEmail({
        to: email,
        subject: 'UREC: Reviewer Deadline Reminder (' + items.length + ' assignment' + (items.length > 1 ? 's' : '') + ')',
        body: body
      });
    } catch (err) {
      console.error('sendReviewerDeadlineReminders_ failed for ' + email + ': ' + err);
    }
  });
}

/**
 * One combined email to every active coordinator listing every
 * application still sitting unassigned past REMINDER_STALE_UNASSIGNED_DAYS.
 */
function sendCoordinatorUnassignedReminders_() {
  var sheet = getSheet_(SHEET_APPLICATIONS);
  var last = sheet.getLastRow();
  if (last < 2) return;

  var now = new Date();
  var values = sheet.getRange(2, 1, last - 1, APP_HEADERS.length).getValues();
  var stale = [];

  values.forEach(function (row) {
    var app = rowToApp_(row);
    if (app.status !== 'Submitted' || !app.submittedAt) return;
    var submitted = new Date(app.submittedAt);
    if (isNaN(submitted.getTime())) return;
    var daysWaiting = Math.floor((now - submitted) / (24 * 60 * 60 * 1000));
    if (daysWaiting < REMINDER_STALE_UNASSIGNED_DAYS) return;

    var form = safeParseJson_(app.formData, {});
    stale.push({
      applicationId: app.applicationId,
      projectTitle: form.projectTitle || '(untitled project)',
      daysWaiting: daysWaiting
    });
  });

  if (!stale.length) return;

  var coordinators = listActiveCoordinators_();
  if (!coordinators.length) return;

  var lines = stale.map(function (a) {
    return '  • ' + a.projectTitle + ' (Ref: ' + a.applicationId + ') — awaiting assignment for ' + a.daysWaiting + ' day(s)';
  });
  var portalUrl = getPortalUrl_();

  coordinators.forEach(function (c) {
    try {
      var body = 'Dear ' + (c.fullName || guessDisplayName_(c.email)) + ',\n\n' +
        'The following submitted application(s) are still awaiting reviewer assignment:\n\n' +
        lines.join('\n') +
        (portalUrl ? ('\n\nOpen the Coordinator Portal: ' + portalUrl) : '') +
        '\n\n— BioEthics Portal, Faculty of Biotechnology, MSA University';

      MailApp.sendEmail({
        to: c.email,
        subject: 'UREC: ' + stale.length + ' Application(s) Awaiting Assignment',
        body: body
      });
    } catch (err) {
      console.error('sendCoordinatorUnassignedReminders_ failed for ' + c.email + ': ' + err);
    }
  });
}

function listActiveCoordinators_() {
  var sheet = getSheet_(SHEET_COORDINATORS);
  var last = sheet.getLastRow();
  if (last < 2) return [];
  var values = sheet.getRange(2, 1, last - 1, COORDINATOR_HEADERS.length).getValues();
  var out = [];
  values.forEach(function (row) {
    var c = rowToCoordinator_(row);
    if (String(c.active).toUpperCase() === 'TRUE') out.push(c);
  });
  return out;
}

/**
 * One-time setup: run this once from the Apps Script editor's function
 * picker to install the daily reminder trigger (7am, script timezone —
 * see appsscript.json's "Africa/Cairo" timeZone). Safe to re-run: it
 * clears any existing checkDeadlinesAndSendReminders trigger first so
 * duplicates never pile up.
 */
function createDailyRemindersTrigger() {
  removeRemindersTriggers_();
  ScriptApp.newTrigger('checkDeadlinesAndSendReminders')
    .timeBased()
    .atHour(7)
    .everyDays(1)
    .create();
}

/**
 * Removes any existing checkDeadlinesAndSendReminders triggers. Called
 * automatically by createDailyRemindersTrigger(); also exposed on its
 * own in case you want to turn reminders off entirely.
 */
function removeRemindersTriggers_() {
  ScriptApp.getProjectTriggers().forEach(function (t) {
    if (t.getHandlerFunction() === 'checkDeadlinesAndSendReminders') {
      ScriptApp.deleteTrigger(t);
    }
  });
}
